/**
 * Older project snapshots persisted the H3 target as `h3` or `minimaxh3`.
 * Keep those aliases usable in the renderer while writing the canonical id
 * back whenever a new target artifact is saved.
 */
const normalizeOfficialTargetId = (value: unknown): string => {
  const raw = typeof value === "string" ? value.trim() : "";
  return isOfficialH3TargetId(raw) ? OFFICIAL_H3_TARGET_ID : raw;
};

const targetIdsMatch = (left: unknown, right: unknown): boolean => {
  const leftRaw = typeof left === "string" ? left.trim() : "";
  const rightRaw = typeof right === "string" ? right.trim() : "";
  if (isOfficialH3TargetId(leftRaw) || isOfficialH3TargetId(rightRaw)) {
    return isOfficialH3TargetId(leftRaw) && isOfficialH3TargetId(rightRaw);
  }
  return leftRaw === rightRaw;
};

