const converterSupportsWorkflow = (
  item: ConverterPreset,
  workflow: Workflow,
): boolean => item.workflow === "all" || item.workflow === workflow;

const converterWorkflowLabel = (item: ConverterPreset): string => (
  item.workflow === "all" ? "通用视频" : workflowLabels[item.workflow]
);

const storyboardShotPlanningFingerprint = (
  shots: readonly VideoShot[],
): string => JSON.stringify(shots.map((shot) => ({
  index: shot.index,
  startSec: shot.startSec,
  endSec: shot.endSec,
  purpose: shot.purpose,
  subject: shot.subject,
  action: shot.action,
  camera: shot.camera,
  transition: shot.transition,
  lighting: shot.lighting,
  sound: shot.sound,
  result: shot.result,
  sourceBeatIds: shot.sourceBeatIds || [],
  sourceStart: shot.sourceStart,
  sourceEnd: shot.sourceEnd,
})));

interface SequenceBatchProgress {
  completed: number;
  total: number;
  currentSegmentIndex?: number;
}

interface StoryboardGenerationOverride {
  sequencePlanId?: string;
  segment?: VideoSegment;
  segmentCount?: number;
  keepDirector?: boolean;
  onFailure?: (reason: string) => void;
  /** Build the authoritative full-duration timeline used by all segments. */
  fullTimeline?: boolean;
  /** Fixed duration grid that a full master timeline must honor. */
  requiredSegmentDurationSec?: number;
  /** Explicit authority for a new full-film draft, never a confirmed slice. */
  durationAdjustmentPolicy?: StoryboardDurationAdjustmentPolicy;
  /** Request-local evidence; the caller commits it only with the complete master. */
  onDurationPlanned?: (estimate: StoryDurationEstimate) => void;
  /** Preserve the exact pacing context used by the preceding duration estimate. */
  pacing?: StoryPacingContext;
  durationSec?: number;
  scene?: Scene;
  sourceScenes?: Scene[];
  workflow?: Workflow;
  shotMode?: ShotMode;
  shotCount?: number;
  /** Return the board to the caller without inserting it into project state. */
  deferCommit?: boolean;
}

const sequenceStoryboardGenerationIdentity = (
  projectId: string,
  sequencePlanId: string,
  segment: VideoSegment,
  segmentCount: number,
): string => JSON.stringify([
  projectId,
  sequencePlanId,
  segment.id,
  segment.content,
  segment.durationSec,
  segment.entryState,
  segment.exitState,
  segment.title,
  segment.summary,
  segment.sourceSceneIds,
  segment.sourceBeatIds,
  segment.index,
  segmentCount,
  segment.globalStartSec,
  segment.globalEndSec,
  segment.transitionHint,
  segment.semanticSource,
  segment.continuityPack,
  Boolean(segment.locked),
]);

const sequenceMasterInputFingerprint = (input: {
  planId: string;
  title: string;
  story: string;
  durationMode: SequenceDurationMode;
  totalDurationSec: number;
  segmentDurationSec: number;
}): string => JSON.stringify([
  input.planId,
  input.title,
  input.story,
  input.durationMode,
  Math.round(input.totalDurationSec * 100) / 100,
  Math.round(input.segmentDurationSec * 100) / 100,
]);

const sequenceMasterSnapshotFingerprint = (
  plan: Pick<
    VideoSequencePlan,
    "id" | "sourceStoryTitle" | "sourceStoryContent" | "durationMode" | "requestedTotalDurationSec" | "totalDurationSec"
    | "segmentDurationSec"
  >,
): string => sequenceMasterInputFingerprint({
  planId: plan.id,
  title: plan.sourceStoryTitle,
  story: plan.sourceStoryContent,
  durationMode: plan.durationMode,
  totalDurationSec: plan.requestedTotalDurationSec ?? plan.totalDurationSec,
  segmentDurationSec: plan.segmentDurationSec,
});

