const combineDirectorScenes = (scenes: Scene[]): Scene | undefined => {
  if (!scenes.length) return undefined;
  if (scenes.length === 1) return scenes[0];
  const primary = scenes[0];
  return {
    ...primary,
    title: scenes.map((scene) => scene.title).join(" + "),
    content: scenes
      .map(
        (scene, index) =>
          `【片段${index + 1}：${scene.title}】\n${scene.content}`,
      )
      .join("\n\n"),
    summary: scenes
      .map(
        (scene, index) => `片段${index + 1}：${scene.summary || scene.content}`,
      )
      .join("；"),
    characterIds: [...new Set(scenes.flatMap((scene) => scene.characterIds))],
    locationIds: [
      ...new Set(
        scenes.flatMap((scene) =>
          scene.locationIds?.length
            ? scene.locationIds
            : scene.locationId
              ? [scene.locationId]
              : [],
        ),
      ),
    ],
    propIds: [...new Set(scenes.flatMap((scene) => scene.propIds))],
  };
};

const buildVideoSegmentScene = (
  segment: VideoSegment,
  sourceScenes: Scene[],
): Scene => {
  const locationIds = [
    ...new Set(
      sourceScenes.flatMap((scene) =>
        scene.locationIds?.length
          ? scene.locationIds
          : scene.locationId
            ? [scene.locationId]
            : [],
      ),
    ),
  ];
  return {
    id: `sequence_scene_${segment.id}`,
    title: segment.title,
    content: segment.content,
    summary: segment.summary,
    characterIds: [
      ...new Set(sourceScenes.flatMap((scene) => scene.characterIds)),
    ],
    ...(locationIds[0] ? { locationId: locationIds[0] } : {}),
    locationIds,
    propIds: [...new Set(sourceScenes.flatMap((scene) => scene.propIds))],
    storyboardIds: [
      ...new Set(sourceScenes.flatMap((scene) => scene.storyboardIds)),
    ],
    createdAt: sourceScenes[0]?.createdAt || 0,
    updatedAt: Math.max(0, ...sourceScenes.map((scene) => scene.updatedAt)),
  };
};

const buildWholeStoryScene = (
  scenes: Scene[],
  story: string,
  title: string,
  characters: Character[] = [],
): Scene | undefined => {
  const combined = combineDirectorScenes(scenes);
  if (!combined) return undefined;
  const content = story.trim() ? story : combined.content;
  return {
    ...combined,
    title: title.trim() || "整段剧情",
    content,
    summary: (() => {
      const source =
        story.trim() ||
        scenes.map((scene) => scene.summary || scene.content).join(" ");
      const compact = source.replace(/\s+/gu, " ").trim();
      return compact.length > 520 ? `${compact.slice(0, 517)}…` : compact;
    })(),
    characterIds: [
      ...new Set([
        ...combined.characterIds,
        ...characters
          .filter((character) => content.includes(character.name))
          .map((character) => character.id),
      ]),
    ],
  };
};

