/**
 * Fields that are safe to refresh when the user explicitly runs the full
 * story analysis again.  The old project merge deliberately keeps every
 * non-empty field so manual dossiers survive a reparse, but that also kept
 * legacy `signatureProps` values which were polluted by transient story
 * objects.  These fields are the small, AI-authoritative slice whose meaning
 * is tied to the complete source story; all other character fields continue
 * through the conservative reconciliation path below.
 *
 * There is no persisted field-level provenance in legacy projects.  An
 * explicit successful reparse therefore treats these returned fields as the
 * user's requested refresh, while preserving the character id, asset links,
 * and every field outside this list.
 */
export const STORY_REANALYSIS_CHARACTER_REFRESH_FIELDS = [
  "signatureProps",
  "anchor",
  "motionHabits",
  "negativeContinuity",
  "appearance",
] as const;

type StoryReanalysisCharacterRefreshField =
  (typeof STORY_REANALYSIS_CHARACTER_REFRESH_FIELDS)[number];

/**
 * Apply the authoritative character slice returned by a full-story rerun.
 * Empty strings are intentional for `signatureProps`: an AI reclassification
 * can conclude that a character has no stable prop, and retaining the old
 * value would recreate the legacy pollution.  Records and assets are cloned
 * so this post-merge refresh cannot mutate an undo snapshot by reference.
 */
export const refreshReanalyzedCharacterFields = (
  existing: readonly Character[],
  authoritative: readonly Record<string, unknown>[],
): Character[] => {
  const recordKey = (record: Record<string, unknown>): string => {
    const rawName = typeof record.name === "string" ? record.name.trim() : "";
    if (!rawName) return "";
    // Share exactly the same form/alias normalization as story analysis and
    // the bible. A bracketed legacy form must match its canonical record,
    // but a bare identity must never refresh another visual form's dossier.
    const canonical = canonicalCharacterVariantName(record);
    return /^(?:我|我们|咱们)$/u.test(canonical)
      ? DEFAULT_FIRST_PERSON_SUBJECT
      : canonical;
  };
  const byName = new Map<string, Partial<Record<StoryReanalysisCharacterRefreshField, string>>>();
  authoritative.forEach((record) => {
    const name = recordKey(record);
    if (!name) return;
    // These stages belong to the same successful full-source request, not to
    // an earlier operation. Keep each field's latest explicit classification:
    // later enrichment may omit a field, but must not undo a correction made
    // by this run's global analysis (especially an intentional empty prop).
    const current: Partial<Record<StoryReanalysisCharacterRefreshField, string>> = {
      ...byName.get(name),
    };
    STORY_REANALYSIS_CHARACTER_REFRESH_FIELDS.forEach((field) => {
      if (!Object.prototype.hasOwnProperty.call(record, field)) return;
      const value = record[field];
      if (typeof value !== "string") return;
      // An empty fixed-prop result is meaningful (the AI has reclassified the
      // old value away).  For ordinary continuity prose, an omitted/blank
      // enrichment field is not deletion evidence and must not erase a
      // manually authored description.
      if (field !== "signatureProps" && !value.trim()) return;
      current[field] = value.trim();
    });
    byName.set(name, current);
  });
  return existing.map((character) => {
    const details = byName.get(recordKey(character as unknown as Record<string, unknown>));
    if (!details) return character;
    const refreshed = {
      ...character,
      assetIds: [...character.assetIds],
    } as Character & Record<string, unknown>;
    STORY_REANALYSIS_CHARACTER_REFRESH_FIELDS.forEach((field) => {
      if (Object.prototype.hasOwnProperty.call(details, field)) {
        const value = details[field];
        if (typeof value === "string") refreshed[field] = value;
      }
    });
    return preserveConfirmedCharacterFields(character, refreshed as Character);
  });
};

type ImageWorkbenchStyleSource = "director" | "manual";

const PRIVATE_CHARACTER_FIELD_SPECS: ReadonlyArray<{
  part: NsfwPrivatePart;
  formKey: string;
  label: string;
}> = [
  { part: "full-body", formKey: "nsfwFullBody", label: "私密全身外貌" },
  { part: "breasts", formKey: "nsfwBreasts", label: "胸部外貌" },
  { part: "vulva", formKey: "nsfwVulva", label: "外阴外貌" },
  { part: "anus", formKey: "nsfwAnus", label: "后庭外貌" },
  { part: "penis", formKey: "nsfwPenis", label: "阴茎外貌" },
  { part: "scrotum", formKey: "nsfwScrotum", label: "阴囊外貌" },
];

const privateCharacterFieldsForGender = (gender: string): typeof PRIVATE_CHARACTER_FIELD_SPECS => {
  const normalized = gender.trim();
  const female = /(?:女|雌|\bfemale\b)/iu.test(normalized);
  const male = /(?:男|雄|\bmale\b)/iu.test(normalized);
  if (female && !male) {
    return PRIVATE_CHARACTER_FIELD_SPECS.filter((item) => (
      ["full-body", "breasts", "vulva", "anus"] as NsfwPrivatePart[]
    ).includes(item.part));
  }
  if (male && !female) {
    return PRIVATE_CHARACTER_FIELD_SPECS.filter((item) => (
      ["full-body", "penis", "scrotum", "anus"] as NsfwPrivatePart[]
    ).includes(item.part));
  }
  return PRIVATE_CHARACTER_FIELD_SPECS;
};

const privateCharacterFourInOneFieldsForGender = (
  gender: string,
  form: Readonly<Record<string, string>> = {},
): typeof PRIVATE_CHARACTER_FIELD_SPECS => {
  const normalized = gender.trim();
  const female = /(?:女|雌|\bfemale\b)/iu.test(normalized);
  const male = /(?:男|雄|\bmale\b)/iu.test(normalized);
  const parts: NsfwPrivatePart[] = female && !male
    ? ["full-body", "breasts", "vulva", "anus"]
    : male && !female
      ? ["full-body", "penis", "scrotum", "anus"]
      : [
          "full-body",
          ...(["breasts", "vulva", "anus", "penis", "scrotum"] as NsfwPrivatePart[])
            .filter((part) => Boolean((form[PRIVATE_CHARACTER_FIELD_SPECS.find((item) => item.part === part)?.formKey || ""] || "").trim()))
            .slice(0, 3),
        ];
  const resolved = parts.length >= 4
    ? parts
    : ["full-body", "breasts", "vulva", "anus"] as NsfwPrivatePart[];
  return PRIVATE_CHARACTER_FIELD_SPECS.filter((item) => resolved.includes(item.part));
};

const isMatchingNsfwPrivateWorkbenchReference = (
  asset: ReferenceAsset | undefined,
  characterId: string,
  privatePart: NsfwPrivatePart,
): asset is ReferenceAsset => Boolean(
  characterId
  && hasUsableStoryboardReferencePixels(asset)
  && isNsfwPrivateProfileAsset(asset)
  && asset.sourceEntityId === characterId
  && (asset.imageVariant === "private-four-in-one" || nsfwPrivatePartForAsset(asset) === privatePart)
);

const durationValue = (preset: DurationPreset, custom: number): number => {
  if (preset === "5s") return 5;
  if (preset === "10s") return 10;
  if (preset === "15s") return 15;
  return Math.max(1, Math.min(300, Number(custom) || 15));
};

const durationPresetForSeconds = (durationSec: number): DurationPreset => {
  if (durationSec === 5) return "5s";
  if (durationSec === 10) return "10s";
  if (durationSec === 15) return "15s";
  return "custom";
};

const isAbortError = (error: unknown): boolean => (
  error instanceof Error && error.name === "AbortError"
);

const formatTime = (value: number): string => {
  if (Number.isInteger(value)) return `${value}s`;
  if (value < 0.1)
    return `${value.toFixed(3).replace(/0+$/, "").replace(/\.$/, "")}s`;
  if (value < 1)
    return `${value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "")}s`;
  return `${value.toFixed(1)}s`;
};

