  const uiSettingsTriggerRef = useRef<HTMLButtonElement>(null);
  const uiSettingsDialogRef = useRef<HTMLDivElement>(null);
  const [runtimeErrorLogOpen, setRuntimeErrorLogOpen] = useState(false);
  const [busy, setBusyInternal] = useState(false);
