  restoreActiveSequenceSegmentSourceContent: () => void;
  splitActiveSequenceSegment: () => void;
  mergeActiveSequenceSegment: () => void;
  moveActiveSequenceSegment: (offset: -1 | 1) => void;
  toggleActiveSequenceSegmentLock: () => void;
