  cameraTerms: string[];
  setCameraTerms: React.Dispatch<React.SetStateAction<string[]>>;
  lightingTerms: string[];
  setLightingTerms: React.Dispatch<React.SetStateAction<string[]>>;
  visualStyle: string;
  setVisualStyle: React.Dispatch<React.SetStateAction<string>>;
