  setSelectedAssetIds: React.Dispatch<React.SetStateAction<string[]>>;
  assetKind: "grid" | "character" | "location" | "prop";
  setAssetKind: React.Dispatch<
    React.SetStateAction<"grid" | "character" | "location" | "prop">
  >;
  assetForm: Record<string, string>;
  setAssetForm: React.Dispatch<React.SetStateAction<Record<string, string>>>;
  assetFormStyleSource: ImageWorkbenchStyleSource;
  setAssetFormStyleSource: React.Dispatch<React.SetStateAction<ImageWorkbenchStyleSource>>;
  handleCopyPrompt: (prompt: string) => Promise<void>;
  buildStoryboard: (
    override?: StoryboardGenerationOverride,
  ) => Promise<Storyboard | undefined>;
  regenerateStoryboardEnglish: (boardId: string) => Promise<void>;
  assetSearch: string;
  setAssetSearch: React.Dispatch<React.SetStateAction<string>>;
  ruleTab: RuleCenterTab;
  setRuleTab: React.Dispatch<React.SetStateAction<RuleCenterTab>>;
  selectedRuleId: string;
  setSelectedRuleId: React.Dispatch<React.SetStateAction<string>>;
  selectedConverterId: string;
  setSelectedConverterId: React.Dispatch<React.SetStateAction<string>>;
  selectedStoryExpansionPresetId: string;
  setSelectedStoryExpansionPresetId: React.Dispatch<React.SetStateAction<string>>;
  selectedStyleId: string;
  setSelectedStyleId: React.Dispatch<React.SetStateAction<string>>;
  selectedImageRuleSetId: string;
  setSelectedImageRuleSetId: React.Dispatch<React.SetStateAction<string>>;
  selectedImagePresetId: string;
