async function regenerateImageTask(ctx: AppContext, requestedTask: ImageGenerationTask) {
  const { setState, setBackgroundState, storyboardImageBatchLifecycle, getCurrentProjectId, setView, notify } = ctx;
  let state = ctx.getCurrentState();
  if (state.project.id !== ctx.state.project.id) {
    notify("项目已切换，请在当前项目重新选择图片。", "error");
    return;
  }
  const tasks = state.project.generationTasks;
  const originalTask = tasks.find((candidate): candidate is ImageGenerationTask => isImageGenerationTask(candidate) && candidate.id === requestedTask.id) || requestedTask;
  const originalTaskWasTracked = tasks.some((candidate) => candidate.id === originalTask.id);
  const originalTaskIdentity = JSON.stringify(originalTask);
  const regenerationKnownSecrets = [state.settings.textApi.apiKey, state.settings.imageApi.apiKey,
    ...(state.settings.imageApiProfiles || []).map((profile) => profile.apiKey)];
  const requestedProjectId = state.project.id;
  const key = `regenerate:${requestedProjectId}:${imageRegenerationRootId(originalTask)}`;
  if (!canRegenerateImageTask(originalTask, tasks)) {
    notify("该图片正在排队或生成，请完成后再重新生图。", "error");
    return;
  }
  // Claim before the asynchronous API fingerprint checks: a second click must
  // not wait for the first generation to finish and then bill a second retry.
  const lease = storyboardImageBatchLifecycle.begin(key);
  if (!lease) return;
  const requestedApiSourceIdentity = imageApiRegenerationSourceIdentity(state.settings, originalTask.imageApiSnapshot);
  let imageApi: AppState["settings"]["imageApi"];
  try {
    imageApi = await resolveImageApiForRegeneration(state.settings, originalTask.imageApiSnapshot);
  } catch (error) {
    storyboardImageBatchLifecycle.finish(lease);
    notify(getSafeErrorDiagnostics(error, {
      knownSecrets: regenerationKnownSecrets,
      sensitiveTexts: [originalTask.conversionSource || "", originalTask.conversionIdentityContext || "", originalTask.converterSystemPrompt || "", originalTask.prompt, originalTask.negativePrompt || ""],
    }).message, "error");
    return;
  }
  const liveState = ctx.getCurrentState();
  const liveOriginal = liveState.project.generationTasks.find((candidate): candidate is ImageGenerationTask => (
    isImageGenerationTask(candidate) && candidate.id === originalTask.id
  ));
  if (!storyboardImageBatchLifecycle.canSubmit(lease) || liveState.project.id !== requestedProjectId
    || imageApiRegenerationSourceIdentity(liveState.settings, originalTask.imageApiSnapshot) !== requestedApiSourceIdentity
    || (originalTaskWasTracked && (!liveOriginal || JSON.stringify(liveOriginal) !== originalTaskIdentity))
    || (!originalTaskWasTracked && originalTask.resultAssetId && !liveState.project.assets.some((asset) => asset.id === originalTask.resultAssetId))
    || !canRegenerateImageTask(liveOriginal || originalTask, liveState.project.generationTasks)) {
    storyboardImageBatchLifecycle.finish(lease);
    notify("项目或原图片任务已变化，本次没有创建重新生图任务或调用图像接口，请重新选择。");
    return;
  }
  state = liveState;
  if (!imageApi.enabled || !imageApi.baseUrl.trim()
    || ((imageApi.backend === "openai" || imageApi.backend === "novelai") && !imageApi.model.trim())) {
    notify("请先启用并配置图像 API，再重新生图。", "error");
    storyboardImageBatchLifecycle.finish(lease);
    setView("settings");
    return;
  }
  if (imageApi.backend !== originalTask.backend) {
    notify(`此任务使用 ${originalTask.backend} 后端，请先切换到同类型图像 API，以免把原提示词发送到不兼容的后端。`, "error");
    storyboardImageBatchLifecycle.finish(lease);
    setView("settings");
    return;
  }
  if (imageApi.backend === "novelai" && !imageApi.apiKey.trim()) {
    notify("请先配置 NovelAI Token/密钥。", "error");
    storyboardImageBatchLifecycle.finish(lease);
    setView("settings");
    return;
  }
  let createdTask: ImageGenerationTask | undefined;
  let imageRequestSubmitted = false;
  const privateRegeneration = originalTask.referenceScope === "nsfw-private-profile"
    || isPrivateImageVariant(originalTask.imageVariant)
    || Boolean(originalTask.nsfwPrivatePart);
  const landscapeRepair = imageTaskNeedsLandscapeScopeRepair(originalTask);
  const privateRegenerationPart: NsfwPrivatePart | undefined = privateRegeneration
    ? originalTask.nsfwPrivatePart
      || (originalTask.imageVariant === "private-full-body"
        || originalTask.imageVariant === "private-five-view"
        || originalTask.imageVariant === "private-turnaround"
        || originalTask.imageVariant === "private-four-in-one"
        ? "full-body"
        : undefined)
    : undefined;
  let convertedPrompt = privateRegeneration || landscapeRepair ? "" : originalTask.prompt;
  let regenerationSource: ReturnType<typeof resolveImageRegenerationSource> | undefined;
  regenerationKnownSecrets.push(state.settings.textApi.apiKey, imageApi.apiKey);
  const submissionCancelledMessage = "重新生图已因撤销或任务状态变化而停止，未调用图像接口。需要生成时请重新点击“重新生图”。";
  const submissionIsCurrent = (task: ImageGenerationTask) => (
    storyboardImageBatchLifecycle.canSubmit(lease)
    && imageBatchTaskIsActive(ctx.getCurrentState(), requestedProjectId, task)
  );
  const assertSubmissionCurrent = () => {
    if (!createdTask || !submissionIsCurrent(createdTask)) throw new GenerationTaskCancelledError(submissionCancelledMessage);
  };
  try {
    const source = resolveImageRegenerationSource(originalTask, state.project);
    regenerationSource = source;
    const textApi = { ...state.settings.textApi };
    const promptKind: ImagePromptAssetKind = privateRegeneration
      ? "character-private"
      : originalTask.assetKind === "character" && (originalTask.imageVariant === "turnaround" || originalTask.imageVariant === "five-view")
        ? "character-sheet"
        : originalTask.assetKind;
    let trace: ImageGenerationTaskPatch = {};
    const requiresPromptConversion = privateRegeneration || landscapeRepair || !originalTask.prompt.trim();
    if (requiresPromptConversion) {
      if (!source.conversionSource.trim()) throw new Error("该旧任务没有保存可恢复的生图资料，请返回工作台重新创建任务。");
      if (!textApi.enabled || !textApi.baseUrl.trim() || !textApi.model.trim()) throw new Error("此任务尚未生成最终提示词，请先配置文本 API 后重试。");
      if (privateRegeneration || landscapeRepair || !source.converterSystemPrompt || !originalTask.imagePromptFormat) {
        const selection = resolveImagePromptSelection({
          backend: imagePromptBackendForApi(imageApi.backend), model: imageApi.model, assetKind: promptKind,
          imageVariant: originalTask.imageVariant,
          manualRuleSetId: state.imagePromptRules.ruleSets.some((rule) => rule.id === originalTask.imagePromptRuleSetId && rule.enabled)
            ? originalTask.imagePromptRuleSetId : undefined,
          manualPresetId: state.imagePromptRules.categoryPresets.some((preset) => preset.id === originalTask.imagePromptPresetId && preset.enabled)
            ? originalTask.imagePromptPresetId : undefined,
          state: state.imagePromptRules,
        });
        source.converterSystemPrompt = buildImagePromptConverterSystemPrompt(
          selection,
          [
            privateRegeneration
              ? privateImageVariantConverterRule(originalTask.imageVariant, privateRegenerationPart)
              : gptImage25MicroNsfwConverterExtraRule(selection, promptKind, originalTask.imageVariant),
            privateRegeneration ? "" : ordinaryImageVariantConverterRule(originalTask.imageVariant),
          ].filter(Boolean).join("\n"),
          originalTask.imageVariant,
        );
        trace = {
          imagePromptRuleSetId: selection.ruleSet.id, imagePromptRuleSetVersion: selection.ruleSet.version,
          imagePromptRuleSetName: selection.ruleSet.name,
          imagePromptPresetId: selection.preset.id, imagePromptPresetVersion: selection.preset.version,
          imagePromptPresetName: selection.preset.name,
          imagePromptFormat: selection.ruleSet.format,
        };
      }
    }
    const referencePreflight = checkNovelAIReferenceImagePreflight(imageApi.backend, [...source.primaryReferenceAssetIds, ...source.referenceAssetIds]);
    if (!referencePreflight.allowed) throw new Error(referencePreflight.message);
    if (originalTask.imageGenerationMode === "image-to-image") assertDirectStoryboardImageApiSupport(imageApi, source.referenceAssetIds.length);
    const task = {
      ...buildImageRegenerationTask(originalTask, state.project, {
        id: createId("image_task"), timestamp: Date.now(), backend: imageApi.backend,
        model: imageApi.backend === "comfyui"
          ? imageApi.comfyuiWorkflows?.find((workflow) => workflow.id === imageApi.activeComfyuiWorkflowId)?.name || "ComfyUI Workflow"
          : imageApi.model.trim(),
        source,
      }),
      ...(privateRegeneration || landscapeRepair ? { prompt: "" } : {}),
      ...trace,
    };
    createdTask = task;
    storyboardImageBatchLifecycle.trackSubmission(lease, task.id);
    setState((current) => applyOwnedProjectUpdate(current, requestedProjectId, (project) => ({
      ...project, generationTasks: [task, ...project.generationTasks],
    })));
    notify(`已加入重新生图队列：${task.name}。原图和原任务会保留。`);
    const sourceAsset = state.project.assets.find((asset) => asset.id === originalTask.resultAssetId);
    await enqueueImageTask(async () => {
      assertSubmissionCurrent();
      setBackgroundState((current) => applyOwnedProjectUpdate(current, requestedProjectId, (project) => ({
        ...project, generationTasks: patchImageGenerationTask(project.generationTasks, task.id, { status: "running", error: undefined }),
      })));
      const cache = new Map<string, Promise<string>>();
      const loader = { readManagedImageDataUrl: window.lianhuaDesktop?.readManagedImageDataUrl, downloadImage: window.lianhuaDesktop?.downloadImage };
      const directImageRetry = task.imageGenerationMode === "image-to-image";
      const referenceAssets = directImageRetry ? imageReferenceSnapshotAssets(source.referenceAssetSnapshots) : state.project.assets;
      const primaryImages = directImageRetry
        ? await resolveDirectStoryboardReferenceImages(source.referenceAssetIds, referenceAssets, loader, cache)
        : await resolveStoryboardReferenceImages(source.primaryReferenceAssetIds, referenceAssets, loader, cache);
      assertSubmissionCurrent();
      const resolvedImages = directImageRetry ? [] : await resolveStoryboardReferenceImages(source.referenceAssetIds, referenceAssets, loader, cache);
      assertSubmissionCurrent();
      const primaryPixels = new Set(primaryImages);
      const result = await executeImageRegeneration(task, {
        referenceImages: [...primaryImages, ...resolvedImages.filter((image) => !primaryPixels.has(image))],
        primaryReferenceImageCount: primaryImages.length,
        convertPrompt: async () => {
          assertSubmissionCurrent();
          const format = task.imagePromptFormat || "natural-language";
          const convertCandidate = async (repair = false): Promise<string> => {
            assertSubmissionCurrent();
            const prompt = await requestImagePromptConverter(
              textApi,
              promptKind,
              source.conversionSource,
              format,
              [
                source.converterSystemPrompt,
                repair && privateRegeneration
                  ? privateImageVariantRepairRule(task.imageVariant, privateRegenerationPart)
                  : "",
              ].filter(Boolean).join("\n"),
              source.conversionIdentityContext,
              task.imageVariant,
            );
            const sanitized = sanitizeFinalImagePrompt(prompt, format);
            return privateRegeneration
              ? normalizePrivateSingleImagePrompt(sanitized, task.imageVariant, format)
              : sanitized;
          };
          let prompt = await convertCandidate();
          if (privateRegeneration) {
            const firstProblem = privateImagePromptProblem(task.imageVariant, prompt, privateRegenerationPart);
            if (firstProblem) {
              prompt = await convertCandidate(true);
              const repairedProblem = privateImagePromptProblem(task.imageVariant, prompt, privateRegenerationPart);
              if (repairedProblem) {
                throw new Error(`私密生图提示词经 AI 自动返修后仍不合格：${repairedProblem}`);
              }
            }
          }
          assertSubmissionCurrent();
          return prompt;
        },
        persistPrompt: (prompt) => {
          assertSubmissionCurrent();
          convertedPrompt = prompt;
          setBackgroundState((current) => applyOwnedProjectUpdate(current, requestedProjectId, (project) => ({
            ...project, generationTasks: patchImageGenerationTask(project.generationTasks, task.id, { prompt }),
          })));
        },
        generateImage: (input) => {
          assertSubmissionCurrent();
          return requestImageModel(imageApi, { ...input, preserveReferenceImageOrder: directImageRetry }, () => {
            // Checked inside the transport FIFO after reference uploads and
            // immediately before the paid generation POST, never just enqueue.
            assertSubmissionCurrent();
            imageRequestSubmitted = true;
          });
        },
      });
      convertedPrompt = result.finalPrompt;
      const actualImageSize = readGeneratedImageDimensions(result.generated.dataUrl || "");
      const imageSizeWarning = imageReturnedSizeWarning(task, actualImageSize);
      const managed = result.generated.dataUrl && window.lianhuaDesktop?.storeGeneratedImage
        ? await window.lianhuaDesktop.storeGeneratedImage({ dataUrl: result.generated.dataUrl, fileName: `${safeFileName(task.name)}.png` })
        : null;
      const dataUrl = managed ? undefined : result.generated.dataUrl;
      const url = managed?.url || result.generated.url;
      if (!dataUrl && !url) throw new Error("图像接口没有返回可保存的图片。");
      const mimeType = result.generated.dataUrl?.match(/^data:([^;,]+)[;,]/iu)?.[1];
      const extension = mimeType === "image/jpeg" ? "jpg" : mimeType === "image/webp" ? "webp" : "png";
      const timestamp = Date.now();
      const roles = { character: "character", location: "scene", prop: "prop", grid: "grid", storyboard: "composition" } as const;
      const asset: ReferenceAsset = {
        id: createId("asset"), name: task.name,
        type: task.imageVariant === "first-frame" ? "first-frame" : task.imageVariant === "last-frame" ? "last-frame"
          : task.assetKind === "storyboard" ? "reference" : task.assetKind,
        role: task.imageVariant === "first-frame" ? "first-frame" : task.imageVariant === "last-frame" ? "last-frame" : roles[task.assetKind],
        dataUrl, url, mimeType, fileName: managed?.fileName || `${safeFileName(task.name)}.${extension}`,
        relativePath: managed?.relativePath, checksum: managed?.checksum, sizeBytes: managed?.sizeBytes,
        managed: Boolean(managed?.managed), missing: false, mediaType: "image", source: "generated",
        prompt: result.finalPrompt, negativePrompt: task.negativePrompt, imageVariant: task.imageVariant,
        imageFrameBatchId: task.imageFrameBatchId,
        imageFrameIndex: task.imageFrameIndex, imageFrameCount: task.imageFrameCount,
        imageFrameDescription: task.imageFrameDescription, imageFrameTimeSec: task.imageFrameTimeSec,
        referenceScope: task.referenceScope,
        nsfwPrivatePart: task.nsfwPrivatePart,
        sourceStoryboardId: task.sourceStoryboardId, sourceShotId: task.sourceShotId, sourceEntityId: task.sourceEntityId,
        sourceEntityKind: task.assetKind === "character" || task.assetKind === "location" || task.assetKind === "prop" ? task.assetKind : undefined,
        visualAnchor: sourceAsset?.visualAnchor, gridStates: sourceAsset?.gridStates?.map((entry) => ({ ...entry })),
        imagePromptRuleSetId: task.imagePromptRuleSetId, imagePromptRuleSetVersion: task.imagePromptRuleSetVersion,
        imagePromptRuleSetName: task.imagePromptRuleSetName,
        imagePromptPresetId: task.imagePromptPresetId, imagePromptPresetVersion: task.imagePromptPresetVersion,
        imagePromptPresetName: task.imagePromptPresetName,
        imagePromptFormat: task.imagePromptFormat, imageBackend: task.backend, width: actualImageSize?.width, height: actualImageSize?.height,
        imageRequestSize: { width: task.width, height: task.height, sizeOverride: task.sizeOverride },
        tags: [...new Set([...(sourceAsset?.tags || []), task.assetKind === "storyboard" ? "剧情分镜" : task.assetKind, "重新生图"])],
        createdAt: timestamp, updatedAt: timestamp,
      };
      setBackgroundState((current) => applyOwnedProjectUpdate(current, requestedProjectId, (project) => {
        const updated = appendRegeneratedImageResult(project, { ...task, prompt: result.finalPrompt }, asset);
        const warnings = [source.warning ? `${source.warning} 原图和原绑定已保留，新图可在资产库手动绑定。` : "", imageSizeWarning].filter(Boolean).join(" ");
        return warnings ? { ...updated, generationTasks: patchImageGenerationTask(updated.generationTasks, task.id, {
          bindingWarning: warnings,
        }) } : updated;
      }));
      if (isCurrentProjectOperation(requestedProjectId, getCurrentProjectId())) notify(imageSizeWarning || `已保存新图：${task.name}${actualImageSize ? ` · 实际 ${actualImageSize.width}×${actualImageSize.height}` : ""}。原图未删除。`);
    });
  } catch (error) {
    const failedTask = createdTask;
    if (failedTask && isGenerationTaskRevoked(requestedProjectId, failedTask)) return;
    const submissionRevoked = Boolean(failedTask && !imageRequestSubmitted && !submissionIsCurrent(failedTask));
    const message = submissionRevoked ? submissionCancelledMessage : getSafeErrorDiagnostics(error, {
      knownSecrets: regenerationKnownSecrets,
      sensitiveTexts: [
        regenerationSource?.conversionSource || "", regenerationSource?.conversionIdentityContext || "", regenerationSource?.converterSystemPrompt || "",
        originalTask.conversionSource || "", originalTask.conversionIdentityContext || "", originalTask.converterSystemPrompt || "",
        convertedPrompt, originalTask.prompt, originalTask.negativePrompt || "",
      ],
    }).message;
    if (failedTask) setBackgroundState((current) => applyOwnedProjectUpdate(current, requestedProjectId, (project) => ({
      ...project,
      // Background updates also rebase history. Patch only an existing active
      // task so redo becomes terminal without resurrecting an undone record.
      // Once a paid POST was sent, keep the original recovery behavior.
      generationTasks: submissionRevoked
        ? project.generationTasks.map((task) => task.id === failedTask.id && isImageGenerationTask(task)
          && (task.status === "queued" || task.status === "running")
          ? { ...task, status: "failed" as const, error: message, updatedAt: Date.now() }
          : task)
        : settleImageGenerationTask(project.generationTasks, failedTask, { status: "failed", prompt: convertedPrompt, error: message }, Date.now(), requestedProjectId),
    })));
    if (isCurrentProjectOperation(requestedProjectId, getCurrentProjectId())) notify(message, "error");
  } finally {
    storyboardImageBatchLifecycle.finish(lease);
  }
}

const videoTaskCanStopBeforeSubmit = (task: VideoGenerationTask): boolean => (
  task.videoJob?.preparation?.version === 1
  && task.videoJob.preparation.phase === "preparing"
  && task.status !== "unknown"
  && task.videoJob.stage !== "submission-unknown"
  && !task.remoteTaskId
  && task.videoJob.batchQueueState !== "cancelled"
  && task.videoJob.batchQueueState !== "done"
  && (!task.videoJob.trackingStopped || task.videoJob.tailPreparation?.phase === "blocked")
);

function GenerationTasksView(ctx: AppContext) {
  const runtimeById = useVideoRuntimes(ctx.videoController.runtimeStore, ctx.videoController.runtimeById);
  const {
    state,
    setState,
    storyboardImageBatchLifecycle,
    activeStoryboard,
    setView,
    notify,
  } = ctx;
  const tasks = (state.project.generationTasks || []).filter(isVisibleGenerationTask);
  const [chapterFilter, setChapterFilter] = useState("all");
  useEffect(() => { setChapterFilter("all"); }, [state.project.id]);
  const chapterFilteredTasks = tasks.filter((task) => (
    chapterFilter === "all" || (chapterIdForTask(state.project, task) || "shared") === chapterFilter
  ));
  const taskChapterLabel = (task: (typeof tasks)[number]) => {
    const chapterId = chapterIdForTask(state.project, task);
    const chapter = state.project.sourceDocuments.find((item) => item.id === chapterId);
    return chapter ? `章节：${chapter.name}${chapter.archived ? "（已归档）" : ""}` : "项目共享 / 历史任务";
  };
  const taskErrorKnownSecrets = [
    state.settings.textApi.apiKey, state.settings.visionApi.apiKey,
    state.settings.imageApi.apiKey, state.settings.videoTaskApi.apiKey,
    state.settings.runningHubVideo?.apiKey || "",
    ...(state.settings.textApiProfiles || []).map((item) => item.apiKey),
    ...(state.settings.visionApiProfiles || []).map((item) => item.apiKey),
    ...(state.settings.imageApiProfiles || []).map((item) => item.apiKey),
    ...(state.settings.videoApiProfiles || []).map((item) => item.apiKey),
    ...state.settings.apiCredentialBook.map((item) => item.apiKey),
  ];
  type TaskCategory = "image" | "video" | "autofill";
  const imageTasks = chapterFilteredTasks.filter(isImageGenerationTask);
  const videoTasks = chapterFilteredTasks.filter(isVideoGenerationTask);
  const autofillTasks = chapterFilteredTasks.filter(isAutofillGenerationTask);
  const [activeTaskCategory, setActiveTaskCategory] = useState<TaskCategory>(() => {
    const newestTask = tasks[0];
    if (newestTask && isImageGenerationTask(newestTask)) return "image";
    if (newestTask && isAutofillGenerationTask(newestTask)) return "autofill";
    return newestTask ? "video" : "image";
  });
  const [expandedVideoBatches, setExpandedVideoBatches] = useState<Set<string>>(() => new Set());
  const [stoppingVideoBatchId, setStoppingVideoBatchId] = useState("");
  const [resumingVideoBatchId, setResumingVideoBatchId] = useState("");
  const [continuingVideoBatchId, setContinuingVideoBatchId] = useState("");
  const [videoBatchContinuation, setVideoBatchContinuation] = useState<VideoBatchContinuationPlan & { displayBatchId: string }>();
  const [videoBatchContinueNotice, setVideoBatchContinueNotice] = useState<{ batchId: string; text: string; error?: boolean }>();
  const videoBatchContinueEpoch = useRef(0);
  const videoBatchContinueAbort = useRef<AbortController>();
  useEffect(() => {
    setVideoBatchContinuation(undefined);
    setVideoBatchContinueNotice(undefined);
    setResumingVideoBatchId("");
    setContinuingVideoBatchId("");
    return () => {
      videoBatchContinueEpoch.current += 1;
      videoBatchContinueAbort.current?.abort();
    };
  }, [state.project.id]);
  const taskCategoryMeta = {
    image: {
      label: "图片任务",
      count: imageTasks.length,
      title: "图片任务在后台依次生成",
      description: "统一查看排队、生成、失败和已保存结果。创建新任务请前往图像工作台。",
      actionLabel: "打开图像工作台",
      emptyTitle: "暂无图片任务",
      emptyDescription: "从图像工作台生成角色、场景、道具、九宫格或分镜图片后，任务会显示在这里。",
    },
    video: {
      label: "视频任务",
      count: videoTasks.length,
      title: "视频任务在后台持续跟踪",
      description: "切换页面不停止查询。提交新任务请到视频导演台选择提示词和图片。",
      actionLabel: "打开视频导演台",
      emptyTitle: "暂无视频任务",
      emptyDescription: "从视频导演台提交生成后，可在这里查看排队、执行、下载和完成状态。",
    },
    autofill: {
      label: "资料任务",
      count: autofillTasks.length,
      title: "资料任务在后台完成补齐",
      description: "人物、地点、道具和九宫格的 AI 资料补齐状态统一在这里查看。",
      actionLabel: "打开资料补充",
      emptyTitle: "暂无资料任务",
      emptyDescription: "在图像工作台点击资料补充后，补齐进度和结果会显示在这里。",
    },
  } as const;
  const activeTaskMeta = taskCategoryMeta[activeTaskCategory];
  const openActiveTaskSource = () => {
    if (activeTaskCategory === "video") {
      ctx.openVideoDirector({ storyboardId: activeStoryboard?.id });
      return;
    }
    setView("image");
  };
  const busyId = "";
  const cancelQueuedTask = (id: string) => {
    const currentState = ctx.getCurrentState();
    const projectId = state.project.id;
    const owner = currentState.project.id === projectId
      ? currentState.project : currentState.projects.find((project) => project.id === projectId);
    const task = owner?.generationTasks.find((candidate) => candidate.id === id);
    if (!task || !owner || (!isImageGenerationTask(task) && !isAutofillGenerationTask(task))) return;
    const result = cancelQueuedGenerationTask(owner.generationTasks, id);
    if (!result.cancelled) {
      notify(task.status === "cancelled" ? "此任务已取消。" : "任务已经开始或状态已变化，没有取消已发出的请求。");
      return;
    }
    // Revoke the worker synchronously before updating the UI or rebasing history.
    revokeQueuedGenerationTask(projectId, task);
    ctx.setBackgroundState((current) => applyOwnedProjectUpdate(current, projectId, (project) => {
      const live = project.generationTasks.find((candidate) => candidate.id === id);
      if (!live || live.kind !== task.kind || live.createdAt !== task.createdAt) return project;
      return { ...project, generationTasks: cancelQueuedGenerationTask(project.generationTasks, id).tasks };
    }));
    storyboardImageBatchLifecycle.releaseCancelledQueuedBatches((taskId) => isImageTaskActiveInWorkspace(ctx.getCurrentState(), taskId));
    notify("已取消此排队任务，其他任务继续；取消记录可以直接删除。");
  };
  /**
   * Cancel and delete local queued video work in one operation. A submitted or
   * uncertain remote task still needs confirmed cancellation before removal;
   * an old local queue label must never discard its recovery record.
   */
  const removeTask = async (id: string) => {
    const currentState = ctx.getCurrentState();
    const currentProject = currentState.project.id === state.project.id
      ? currentState.project
      : [...currentState.projects, currentState.project].find((project) => project.id === state.project.id);
    const task = currentProject?.generationTasks.find((candidate) => candidate.id === id);
    if (!task || !currentProject) return;
    const queuedVideoDeletion = isVideoGenerationTask(task) && isUnsubmittedVideoTask(task);
    if ((isImageGenerationTask(task) || isAutofillGenerationTask(task)) && task.status === "queued") {
      revokeQueuedGenerationTask(currentProject.id, task);
      ctx.setBackgroundState((current) => applyOwnedProjectUpdate(current, currentProject.id, (project) => {
        const live = project.generationTasks.find((candidate) => candidate.id === id);
        if (!live || live.kind !== task.kind || live.createdAt !== task.createdAt) return project;
        const cancelled = cancelQueuedGenerationTask(project.generationTasks, id);
        return { ...project, generationTasks: removeGenerationTask(cancelled.tasks, id).tasks };
      }));
      storyboardImageBatchLifecycle.releaseCancelledQueuedBatches((taskId) => isImageTaskActiveInWorkspace(ctx.getCurrentState(), taskId));
      notify("已从队列删除此任务，不再提交生成；已有图片和资料不受影响。");
      return;
    }
    if (isVideoGenerationTask(task)) {
      const runtime = runtimeById[task.id];
      const stage = videoTaskBatchStatus(task, runtime);
      const active = !["succeeded", "failed", "stopped"].includes(stage);
      const deleteQueued = isUnsubmittedVideoTask(task);
      if (active || deleteQueued) {
        try {
          await ctx.videoController.cancel(id);
          if (!deleteQueued) {
            notify("已请求取消此视频任务；已提交的远端任务记录暂时保留，确认结束后可删除。", "normal");
            return;
          }
          const checkedState = ctx.getCurrentState();
          const checkedProject = checkedState.project.id === currentProject.id
            ? checkedState.project : checkedState.projects.find((project) => project.id === currentProject.id);
          const checkedTask = checkedProject?.generationTasks.find((candidate) => candidate.id === id);
          if (!checkedTask || !isVideoGenerationTask(checkedTask)) return;
          if (!isUnsubmittedVideoTask(checkedTask) || !checkedTask.videoJob?.cancellationConfirmed
            || videoTaskHasUnresolvedSubmission(checkedTask)) {
            notify("任务已开始提交或远端取消尚未确认，已保留任务记录；可恢复查询确认结果后删除。", "normal");
            return;
          }
        } catch (cause) {
          notify(formatUserFacingError(cause), "error");
          return;
        }
      }
      if (!active && videoTaskHasUnresolvedSubmission(task)) {
        notify("远端结果尚未确认，需要保留原任务记录以便恢复查询。已停止跟踪的任务不会占用本机并发名额。", "error");
        return;
      }
    }
    const latestState = ctx.getCurrentState();
    const latestProject = latestState.project.id === state.project.id
      ? latestState.project
      : [...latestState.projects, latestState.project].find((project) => project.id === state.project.id);
    const latestTasks = latestProject?.generationTasks || [];
    const latestTask = latestTasks.find((candidate) => candidate.id === id);
    if (!latestTask || latestTask.kind !== task.kind || latestTask.createdAt !== task.createdAt) return;
    const preview = removeGenerationTask(latestTasks, id, busyId);
    if (preview.blocked) {
      const latestTask = latestTasks.find((candidate) => candidate.id === id);
      notify(
        latestTask && isAutofillGenerationTask(latestTask)
          ? "AI 补齐任务仍在运行，完成或失败后才能删除。"
          : latestTask && isVideoGenerationTask(latestTask)
            ? latestTask.status === "submitting"
              ? "视频任务仍在提交，请等待提交完成或失败后再删除。"
              : "视频任务的本地请求仍在处理，请稍候再删除。"
            : "图片任务仍在生成，完成或失败后才能删除。",
        "error",
      );
      return;
    }
    if (!preview.removed || !latestProject) return;
    const requestedProjectId = latestProject.id;
    const commitRemoval = queuedVideoDeletion ? ctx.setBackgroundState : setState;
    commitRemoval((current: AppState) => applyOwnedProjectUpdate(
      current,
      requestedProjectId,
      (project) => {
        const liveVideoTask = project.generationTasks.find((candidate) => candidate.id === id);
        if (!liveVideoTask || liveVideoTask.kind !== task.kind || liveVideoTask.createdAt !== task.createdAt) return project;
        if (liveVideoTask && isVideoGenerationTask(liveVideoTask) && videoTaskHasUnresolvedSubmission(liveVideoTask)) return project;
        const result = removeVideoTaskKeepingProvenance(project, id, busyId);
        return result.removed
          ? result.project
          : project;
      },
    ));
    if (queuedVideoDeletion) notify("已取消并删除尚未提交的视频任务，其他任务继续。");
  };
  const videoBatchDeletionBusyReason = (batchId: string) => (
    resumingVideoBatchId || continuingVideoBatchId || stoppingVideoBatchId
      ? "正在处理批次，请完成后再删除。"
      : videoBatchContinuation && [videoBatchContinuation.displayBatchId, videoBatchContinuation.batchId].includes(batchId)
        ? "请先在继续批次的确认区点击“暂不继续”，再删除批次。" : ""
  );
  const removeVideoBatch = (batchId: string) => {
    const busyReason = videoBatchDeletionBusyReason(batchId);
    if (busyReason) { notify(busyReason); return; }
    const projectId = state.project.id;
    if (ctx.getCurrentState().project.id !== projectId) {
      notify("项目已切换，请在当前项目重新选择批次。");
      return;
    }
    let removedCount = 0;
    let reason = "";
    setState((current) => {
      if (current.project.id !== projectId) return current;
      return applyOwnedProjectUpdate(current, projectId, (project) => {
        const result = removeVideoBatchKeepingProvenance(project, {
          projectId, batchId,
          getRuntime: (taskId) => ctx.videoController.runtimeStore?.getTaskSnapshot(taskId)
            || ctx.videoController.runtimeById[taskId],
        });
        removedCount = result.removedTaskIds.length;
        reason = result.reason || "";
        return result.project;
      });
    });
    if (!removedCount) { if (reason) notify(reason); return; }
    setExpandedVideoBatches((current) => {
      const next = new Set(current);
      next.delete(batchId);
      return next;
    });
    setVideoBatchContinueNotice((current) => current?.batchId === batchId ? undefined : current);
    notify(`已删除本批次的 ${removedCount} 条任务记录，已生成的视频和素材保留。`);
  };
  const videoTaskGroups = (() => {
    const result: Array<{ key: string; batchId?: string; tasks: VideoGenerationTask[] }> = [];
    const batches = new Map<string, { key: string; batchId: string; tasks: VideoGenerationTask[] }>();
    videoTasks.forEach((task) => {
      if (!task.batchId) {
        result.push({ key: `task:${task.id}`, tasks: [task] });
        return;
      }
      let group = batches.get(task.batchId);
      if (!group) {
        group = { key: `batch:${task.batchId}`, batchId: task.batchId, tasks: [] };
        batches.set(task.batchId, group);
        result.push(group);
      }
      group.tasks.push(task);
    });
    result.forEach((group) => group.tasks.sort((left, right) => (
      (left.batchIndex || Number.MAX_SAFE_INTEGER) - (right.batchIndex || Number.MAX_SAFE_INTEGER)
      || left.createdAt - right.createdAt
    )));
    return result;
  })();
  const renderVideoTask = (task: VideoGenerationTask) => {
    const live = runtimeById[task.id] || task.videoJob;
    const status = videoTaskBatchStatus(task, runtimeById[task.id]);
    const awaitingResultChoice = Boolean(task.videoJob?.resultSelectionRequired)
      || runningHubRemoteSucceeded(task) && !task.resultAssetId && live?.stage !== "downloading";
    const active = !["succeeded", "failed", "stopped"].includes(status) && !awaitingResultChoice;
    const localQueued = active && isUnsubmittedVideoTask(task);
    const cancellationPending = Boolean(live?.cancellationPending);
    const removable = !active && !cancellationPending && !videoTaskHasUnresolvedSubmission(task) && (task.status === "failed"
      || task.status === "succeeded" && live?.stage !== "downloading"
      || live?.trackingStopped);
    return <Fragment key={task.id}>
      <div className="field-hint task-chapter-label">{taskChapterLabel(task)}</div>
      <VideoTaskCard
        task={task}
        assets={state.project.assets}
        runtime={runtimeById[task.id]}
        runtimeStore={ctx.videoController.runtimeStore}
        knownSecrets={taskErrorKnownSecrets}
        onRetryDownload={ctx.videoController.retryDownload}
        onRecoverResult={ctx.videoController.recoverResult}
        onSelectResultVideo={ctx.videoController.selectResultVideo}
        onResume={ctx.videoController.resume}
        onCancel={ctx.videoController.cancel}
        onReuse={(item) => ctx.openVideoDirector({ taskId: item.id })}
        onOpenPrompt={ctx.openPromptSource}
      />
      {cancellationPending && <div className="field-hint">正在确认远端取消状态，确认完成后可删除任务记录。</div>}
      {(removable || active) && <div className="row">
        <Button
          small
          variant={active ? "danger" : "ghost"}
          icon={active && !localQueued ? <X size={13} /> : <Trash2 size={13} />}
          disabled={cancellationPending}
          title={localQueued ? "取消尚未提交的排队任务并直接删除，不影响其他任务" : active ? "先停止本地跟踪并请求取消远端排队；任务记录会保留，确认停止后再删除" : "删除任务记录，已生成的成片会保留在资产库"}
          onClick={() => { void removeTask(task.id); }}
        >
          {localQueued ? "删除任务" : active ? "取消任务" : "删除任务记录（保留成片）"}
        </Button>
      </div>}
    </Fragment>;
  };
  const stopVideoBatch = async (batchId: string) => {
    if (stoppingVideoBatchId) return;
    setStoppingVideoBatchId(batchId);
    try {
      const result = await ctx.videoController.cancelBatch(batchId);
      notify(
        result.cancelledTaskIds.length
          ? `已停止 ${result.cancelledTaskIds.length} 个尚未提交的视频任务；${result.retainedTaskIds.length} 个已提交任务继续运行。`
          : "这个批次没有尚未提交的任务，已提交任务继续运行。",
      );
    } catch (cause) {
      notify(formatUserFacingError(cause), "error");
    } finally {
      setStoppingVideoBatchId("");
    }
  };
  const resumeVideoBatch = async (batchId: string) => {
    if (!ctx.videoController.resumeBatch || resumingVideoBatchId || continuingVideoBatchId) return;
    const projectId = state.project.id;
    const epoch = ++videoBatchContinueEpoch.current;
    const isCurrent = () => epoch === videoBatchContinueEpoch.current && ctx.getCurrentState().project.id === projectId;
    setResumingVideoBatchId(batchId);
    setVideoBatchContinuation(undefined);
    setVideoBatchContinueNotice(undefined);
    try {
      const result = await ctx.videoController.resumeBatch(batchId);
      if (!isCurrent()) return;
      setVideoBatchContinuation(result.continuation ? { ...result.continuation, displayBatchId: batchId } : undefined);
      const details = [
        result.completedTaskIds.length ? `${result.completedTaskIds.length} 项已完成，保持原成片。` : "",
        result.resumedTaskIds.length ? `已恢复 ${result.resumedTaskIds.length} 项原任务的查询或结果保存。` : "",
        result.waitingTaskIds.length ? `${result.waitingTaskIds.length} 项尚未完成；已提交的只跟踪原任务，需要新生成的先确认费用。` : "",
        ...result.issues.map((issue) => formatUserFacingError(issue.message)),
      ].filter(Boolean).join(" ");
      setVideoBatchContinueNotice({ batchId, text: details || (result.continuation
        ? "未完成项已按原任务快照整理，请确认后继续。"
        : "当前没有需要继续的项目。"), error: result.issues.length > 0 });
      if (result.issues.length) setExpandedVideoBatches((current) => new Set([...current, batchId]));
    } catch (cause) {
      if (isCurrent()) setVideoBatchContinueNotice({ batchId, text: formatUserFacingError(cause), error: true });
    } finally {
      if (isCurrent()) setResumingVideoBatchId("");
    }
  };
  const cancelVideoBatchContinuation = () => {
    const plan = videoBatchContinuation;
    const wasPreparing = Boolean(videoBatchContinueAbort.current);
    videoBatchContinueEpoch.current += 1;
    videoBatchContinueAbort.current?.abort();
    videoBatchContinueAbort.current = undefined;
    setVideoBatchContinuation(undefined);
    setContinuingVideoBatchId("");
    setResumingVideoBatchId("");
    if (plan) setVideoBatchContinueNotice({ batchId: plan.displayBatchId, text: wasPreparing
      ? "已请求取消续跑准备；已发出的接口请求可能已计费，请以任务状态为准。"
      : "已取消本次确认，未提交新的生成。" });
  };
  const confirmVideoBatchContinuation = async () => {
    const plan = videoBatchContinuation;
    if (!plan || !ctx.videoController.confirmContinueBatch || continuingVideoBatchId || videoBatchContinueAbort.current) return;
    const epoch = ++videoBatchContinueEpoch.current;
    const controller = new AbortController();
    videoBatchContinueAbort.current = controller;
    const isCurrent = () => epoch === videoBatchContinueEpoch.current && ctx.getCurrentState().project.id === plan.projectId;
    setContinuingVideoBatchId(plan.displayBatchId);
    setVideoBatchContinueNotice({ batchId: plan.displayBatchId, text: plan.requiresAiTail
      ? "正在由 AI 准备准确上一段的衔接帧，完成后继续未完成项…"
      : "正在核对原始快照并创建未完成项的续跑批次…" });
    try {
      const result = await ctx.videoController.confirmContinueBatch(plan.id, controller.signal);
      if (!isCurrent()) return;
      setVideoBatchContinuation(undefined);
      setVideoBatchContinueNotice({ batchId: plan.displayBatchId, text: `已继续 ${result.taskIds.length} 个未完成项；原成功成片与旧批次记录保留，新任务显示在续跑批次中。` });
      setExpandedVideoBatches((current) => new Set([...current, result.batchId]));
    } catch (cause) {
      if (isCurrent() && !controller.signal.aborted) {
        setVideoBatchContinuation(undefined);
        setVideoBatchContinueNotice({ batchId: plan.displayBatchId, text: formatUserFacingError(cause), error: true });
      }
    } finally {
      if (isCurrent()) setContinuingVideoBatchId("");
      if (videoBatchContinueAbort.current === controller) videoBatchContinueAbort.current = undefined;
    }
  };
  const renderVideoTaskGroup = (group: (typeof videoTaskGroups)[number]) => {
    if (!group.batchId) return renderVideoTask(group.tasks[0]);
    const hiddenTaskCount = tasks.filter((task) => isVideoGenerationTask(task) && task.batchId === group.batchId).length - group.tasks.length;
    const partialBatchReason = hiddenTaskCount > 0 ? `章节筛选隐藏了本批次 ${hiddenTaskCount} 项；选择“全项目 · 全部章节”后可操作整个批次。` : "";
    const counts: Record<VideoTaskBatchStatus, number> = {
      pending: 0,
      submitting: 0,
      queued: 0,
      running: 0,
      succeeded: 0,
      failed: 0,
      unknown: 0,
      stopped: 0,
    };
    group.tasks.forEach((task) => {
      counts[videoTaskBatchStatus(task, runtimeById[task.id])] += 1;
    });
    const expanded = expandedVideoBatches.has(group.batchId);
    const deletion = inspectVideoBatchDeletion(state.project, {
      projectId: state.project.id, batchId: group.batchId,
      getRuntime: (taskId) => runtimeById[taskId],
    });
    const deleteDisabledReason = partialBatchReason || videoBatchDeletionBusyReason(group.batchId) || deletion.reason;
    const stoppable = group.tasks.filter(videoTaskCanStopBeforeSubmit).length;
    const chainBatch = group.tasks.some((task) => task.videoJob?.snapshot.batchCompletionOrder);
    const retryableFailures = group.tasks.filter((task) => {
      const snapshot = task.videoJob?.snapshot;
      const source = snapshot?.draft.source;
      return videoTaskBatchStatus(task, runtimeById[task.id]) === "failed"
        && !runningHubRemoteSucceeded(task)
        && !task.videoJob?.downloadError
        && !runtimeById[task.id]?.downloadError
        && !task.videoJob?.legacyMetadataIncomplete
        && Boolean(snapshot?.draft.prompt.trim())
        && Boolean(source?.sequencePlanId || task.sequencePlanId)
        && Boolean(source?.segmentId || task.segmentId)
        && Boolean(source?.storyboardId || task.storyboardId);
    });
    const zhCount = group.tasks.filter((task) => task.videoJob?.snapshot.draft.source?.language !== "en").length;
    const linkedCount = group.tasks.filter((task) => task.videoJob?.snapshot.previousTail).length;
    const tailWaitingCount = group.tasks.filter((task) => task.videoJob?.tailPreparation?.phase === "waiting").length;
    const tailExtractingCount = group.tasks.filter((task) => task.videoJob?.tailPreparation?.phase === "extracting").length;
    const tailBlockedCount = group.tasks.filter((task) => task.videoJob?.tailPreparation?.phase === "blocked").length;
    const resultSelectionCount = group.tasks.filter((task) => task.videoJob?.resultSelectionRequired).length;
    const cloudRecoveryCount = group.tasks.filter((task) => !task.videoJob?.resultSelectionRequired
      && !task.resultAssetId && runningHubRemoteSucceeded(task)
      && videoTaskBatchStatus(task, runtimeById[task.id]) === "pending").length;
    const enCount = group.tasks.length - zhCount;
    const title = group.tasks[0]?.batchLabel || "长剧情批量视频";
    const batchPanelId = `video-batch-tasks-${group.batchId.replace(/[^a-zA-Z0-9_-]/gu, "-")}`;
    return <section className="video-task-batch" key={group.key} data-video-batch-id={group.batchId}>
      <div className="video-task-batch-header">
        <div className="video-task-batch-copy">
          <div className="row wrap">
            <Badge tone="violet">批量视频</Badge>
            {linkedCount > 0 && <Badge tone="cyan">自动尾帧接续</Badge>}
            <strong>{title}</strong>
          </div>
          <div className="field-hint">
            共 {group.tasks.length} 项 · 中文 {zhCount} · 英文 {enCount} · {new Date(Math.max(...group.tasks.map((task) => task.createdAt))).toLocaleString()}
          </div>
          <div className="field-hint task-chapter-label">{[...new Set(group.tasks.map(taskChapterLabel))].join(" · ")}</div>
          <div className="video-task-batch-counts" aria-label="批次任务状态汇总">
            <span>待提交 {Math.max(0, counts.pending - resultSelectionCount - cloudRecoveryCount)}</span>
            {resultSelectionCount > 0 && <span>待选择成片 {resultSelectionCount}</span>}
            {cloudRecoveryCount > 0 && <span>云端成功待取回 {cloudRecoveryCount}</span>}
            <span>提交中 {counts.submitting}</span>
            <span>排队 {counts.queued}</span>
            <span>运行 {counts.running}</span>
            <span className="succeeded">成功 {counts.succeeded}</span>
            <span className={counts.failed ? "failed" : undefined}>失败 {counts.failed}</span>
            {counts.unknown > 0 && <span className="unknown">待确认 {counts.unknown}</span>}
            {counts.stopped > 0 && <span>已停止 {counts.stopped}</span>}
            {tailWaitingCount > 0 && <span>等待上段 {tailWaitingCount}</span>}
            {tailExtractingCount > 0 && <span>抽取尾帧 {tailExtractingCount}</span>}
            {tailBlockedCount > 0 && <span className="failed">衔接待处理 {tailBlockedCount}</span>}
          </div>
          {chainBatch && (counts.failed > 0 || counts.stopped > 0) && <p className="field-hint">点击“继续批次”恢复未完成项：已成功成片不重做，已提交任务先查询或取回结果；需要重新生成或重新 AI 选帧时会先列出清单，确认后继续。旧批次记录保留。</p>}
        </div>
        <div className="video-task-batch-actions">
          <Button
            small
            variant="primary"
            icon={<Play size={13} />}
            disabled={Boolean(partialBatchReason) || !ctx.videoController.resumeBatch || counts.succeeded === group.tasks.length || Boolean(resumingVideoBatchId || continuingVideoBatchId || stoppingVideoBatchId)}
            title={partialBatchReason || "继续未完成项；已成功成片不重做，可能重新收费的生成先确认"}
            onClick={() => void resumeVideoBatch(group.batchId!)}
          >
            {resumingVideoBatchId === group.batchId ? "正在检查…" : continuingVideoBatchId === group.batchId ? "正在继续…" : "继续批次"}
          </Button>
          {counts.failed > 0 && !chainBatch && <Button
            small
            variant="ghost"
            disabled={!retryableFailures.length}
            title={retryableFailures.length
              ? `把 ${retryableFailures.length} 个失败项的原提示词、参数和参考图快照带回批量页复核，不会立即提交`
              : group.tasks.some((task) => task.videoJob?.downloadError)
                ? "成片保存失败请在任务卡重试下载，不需要再次付费生成"
                : "失败项缺少完整原始快照，不能保证按原设置重试"}
            onClick={() => ctx.openVideoDirector({ batchTaskIds: retryableFailures.map((task) => task.id) })}
          >
            只重试失败项{retryableFailures.length ? `（${retryableFailures.length}）` : ""}
          </Button>}
          <Button
            small
            variant="ghost"
            disabled={Boolean(partialBatchReason) || !stoppable || Boolean(stoppingVideoBatchId || resumingVideoBatchId || continuingVideoBatchId)}
            title={partialBatchReason || (stoppable ? `停止此批次中 ${stoppable} 个尚未提交的任务，不影响已提交任务` : "此批次没有可停止的未提交任务")}
            onClick={() => void stopVideoBatch(group.batchId!)}
          >
            {stoppingVideoBatchId === group.batchId ? "正在停止…" : `停止未提交项${stoppable ? `（${stoppable}）` : ""}`}
          </Button>
          <button
            type="button"
            className="btn small video-task-batch-toggle"
            aria-expanded={expanded}
            aria-controls={batchPanelId}
            onClick={() => setExpandedVideoBatches((current) => {
              const next = new Set(current);
              if (next.has(group.batchId!)) next.delete(group.batchId!);
              else next.add(group.batchId!);
              return next;
            })}
          >
            {expanded ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
            <span>{expanded ? "收起任务" : `展开 ${group.tasks.length} 个任务`}</span>
          </button>
        </div>
      </div>
      {videoBatchContinueNotice?.batchId === group.batchId && <p className={videoBatchContinueNotice.error ? "prompt-validation invalid" : "field-hint"} role={videoBatchContinueNotice.error ? "alert" : "status"}>{videoBatchContinueNotice.text}</p>}
      {videoBatchContinuation?.displayBatchId === group.batchId && <section className="video-batch-continue-confirm" role="region" aria-label="确认继续未完成的视频任务">
        <strong>继续 {videoBatchContinuation.items.length} 个未完成项</strong>
        <p>使用原任务保存的提示词、参数和参考图，不重做 {videoBatchContinuation.completedTaskIds.length} 个成功项。未提交项会首次生成；已失败项重新生成可能再次收费。</p>
        <p>若后续项包含自动尾帧衔接，也会按原设置调用 AI 选帧，可能产生视觉接口费用。</p>
        {videoBatchContinuation.requiresAiTail && <p>缺少衔接帧的项目会从准确的已成功上一段进行 AI 选帧，可能产生视觉接口费用；不会擅自换用其它视频。</p>}
        <ul>{videoBatchContinuation.items.map((item) => <li key={item.taskId}>{item.segmentIndex ? `第 ${item.segmentIndex} 段 · ` : ""}{item.name} — {item.willRegenerate ? "重新生成（可能再次收费）" : "继续尚未提交的生成"}</li>)}</ul>
        <div className="row wrap">
          <Button small variant="primary" disabled={Boolean(continuingVideoBatchId || partialBatchReason)} title={partialBatchReason || undefined} onClick={() => void confirmVideoBatchContinuation()}>
            {continuingVideoBatchId ? "正在准备续跑…" : `确认继续 ${videoBatchContinuation.items.length} 项（可能收费）`}
          </Button>
          <Button small variant="ghost" onClick={cancelVideoBatchContinuation}>{continuingVideoBatchId ? "取消续跑准备" : "暂不继续"}</Button>
        </div>
      </section>}
      {expanded && <div id={batchPanelId} className="video-task-batch-items">{group.tasks.map(renderVideoTask)}</div>}
      <div className="video-task-batch-footer">
        {deleteDisabledReason && <span className="field-hint video-task-batch-delete-reason" role="note" data-video-batch-delete-reason>
          {deleteDisabledReason}
        </span>}
        <Button small variant="danger" icon={<Trash2 size={13} />} ariaLabel="删除批次"
          disabled={!deletion.canDelete || Boolean(deleteDisabledReason)}
          title={deleteDisabledReason || "删除本批次全部任务记录，保留已生成的视频和素材；可通过顶部撤销恢复记录"}
          onClick={() => removeVideoBatch(group.batchId!)}>
          删除批次
        </Button>
      </div>
    </section>;
  };
  const renderImageTaskCard = (task: ImageGenerationTask) => {
    const resultAsset = task.resultAssetId
      ? state.project.assets.find((asset) => asset.id === task.resultAssetId)
      : undefined;
    const previewUrl = resultAsset ? assetPreviewUrl(resultAsset) : task.resultUrl || "";
    const promptConfig = imageTaskRuleMetadata(task, state.imagePromptRules, resultAsset);
    const variantLabel = getImageVariantGenerationSpec(task.imageVariant)?.label || task.imageVariant;
    const canRegenerate = canRegenerateImageTask(task, tasks)
      && !storyboardImageBatchLifecycle.isActive(`regenerate:${state.project.id}:${imageRegenerationRootId(task)}`);
    return (
      <Card key={task.id} id={`image-task-${task.id}`} className="job-card image-job-card regeneratable-image-task">
        <div className="row-between job-card-header">
          <div className="image-job-summary">
            {previewUrl && (
              <img
                className="image-job-preview"
                src={previewUrl}
                alt={`${task.name} 生成结果`}
              />
            )}
            <div className="job-card-copy">
              <div className="row wrap">
                <Badge tone="violet">图像</Badge>
                {task.imageGenerationMode === "image-to-image" && <Badge tone="green">分镜图生图</Badge>}
                <Badge tone={task.status === "succeeded" ? "green" : task.status === "failed" ? "pink" : "violet"}>
                  {imageGenerationStatusLabel(task.status)}
                </Badge>
                <strong>{task.name}</strong>
              </div>
              <div className="field-hint task-chapter-label">{taskChapterLabel(task)}</div>
              <div className="field-hint">
                {imageAssetKindLabel(task.assetKind)} · {variantLabel} · 请求 {task.width}×{task.height}{resultAsset?.imageRequestSize && resultAsset.width && resultAsset.height ? ` · 实际 ${resultAsset.width}×${resultAsset.height}` : ''} · {task.model || task.backend} · {new Date(task.updatedAt).toLocaleString()}
              </div>
              <div className="field-hint image-task-prompt-config" aria-label="本次生图规则与预设">
                <span title={promptConfig.rule.title}><strong>生图规则：</strong>{promptConfig.rule.text}</span>
                <span title={promptConfig.preset.title}><strong>分类预设：</strong>{promptConfig.preset.text}</span>
              </div>
              {task.imageGenerationMode === "image-to-image" && <div className="field-hint">
                原始参考图 {task.referenceAssetSnapshots?.length || 0} 张：{task.referenceAssetSnapshots?.map((asset) => asset.name).join("、") || "快照缺失"}
                {task.sourceShotId && ` · 镜头 ${state.project.storyboards.find((board) => board.id === task.sourceStoryboardId)?.shots.find((shot) => shot.id === task.sourceShotId)?.index || task.sourceShotId}`}
              </div>}
              <div className="field-hint job-prompt" title={task.prompt || "等待转换器生成最终生图提示词"}>
                {task.prompt || "等待转换器生成最终生图提示词"}
              </div>
            </div>
          </div>
          <div className="row wrap job-card-actions">
            {task.status === "queued" && <Button small variant="danger" icon={<X size={13} />}
              title="取消此排队任务，保留一条已取消记录，不影响其他任务"
              onClick={() => cancelQueuedTask(task.id)}>取消排队</Button>}
            <Button
              small
              variant="primary"
              className="image-regenerate-button"
              icon={<RefreshCw size={13} />}
              disabled={!canRegenerate}
              title={canRegenerate ? `重新生图：${task.name}。${task.imageApiSnapshot ? "沿用原生图 API 配置和尺寸" : "沿用提示词和尺寸，使用当前图像 API"}，保留原图。` : "任务正在排队或生成，请完成后再重新生图。"}
              onClick={() => void regenerateImageTask(ctx, task)}
            >
              重新生图
            </Button>
            <Button
              small
              variant="ghost"
              icon={<Copy size={13} />}
              disabled={!task.prompt?.trim()}
              title={task.prompt?.trim() ? `复制「${task.name}」的完整最终提示词，不受预览省略影响` : "最终提示词尚未生成，生成后即可复制"}
              ariaLabel={`复制「${task.name}」的最终提示词`}
              onClick={async () => {
                if (!task.prompt?.trim()) return;
                let copied = false;
                try {
                  copied = await copyText(task.prompt);
                } catch {
                  // Clipboard permissions/fallback may fail; never alter or retry the task.
                }
                notify(
                  copied ? `已复制「${task.name}」的完整最终提示词。` : `未能复制「${task.name}」的最终提示词，请检查剪贴板权限后重试。`,
                  copied ? "normal" : "error",
                );
              }}
            >
              复制最终提示词
            </Button>
            {task.resultUrl && (
              <Button small icon={<Eye size={13} />} onClick={() => window.lianhuaDesktop?.openExternal(task.resultUrl!)}>
                打开图片
              </Button>
            )}
            {task.resultAssetId && (
              <Button small variant="ghost" onClick={() => { ctx.setAssetLibrarySection("image"); ctx.setVideoAssetStoryboardFilter(""); setView("assets"); }}>
                查看资产
              </Button>
            )}
            {task.status === "failed" && (
              <Button small variant="ghost" onClick={() => setView(task.assetKind === "storyboard" ? "director" : "image")}>
                {task.assetKind === "storyboard" ? "返回提示词导演台" : "返回图像工作台"}
              </Button>
            )}
            <Button
              small
              variant={task.status === "running" ? "ghost" : "danger"}
              icon={<Trash2 size={13} />}
              disabled={task.status === "running"}
              title={task.status === "running" ? "请求已开始，生成完成或失败后可删除" : task.status === "queued" ? "直接移出队列并删除，不再提交生成；已有图片保留" : "删除任务记录，已有图片保留"}
              onClick={() => removeTask(task.id)}
            >
              {task.status === "running" ? "不可删除" : "删除"}
            </Button>
          </div>
        </div>
        {task.bindingWarning && <div className="hint-box compact-hint">{task.bindingWarning}</div>}
        {task.error && <TaskErrorDetails error={task.error} className="prompt-validation invalid"
          knownSecrets={taskErrorKnownSecrets}
          sensitiveTexts={[task.prompt || "", task.negativePrompt || "", task.conversionSource || "", task.conversionIdentityContext || "", task.converterSystemPrompt || ""]} />}
      </Card>
    );
  };
  const renderAutofillTaskCard = (task: AutofillGenerationTask) => {
    const completedFieldCount = Object.keys(task.result || {}).length;
    return (
      <Card key={task.id} id={`autofill-task-${task.id}`} className="job-card image-job-card">
        <div className="row-between job-card-header">
          <div className="job-card-copy">
            <div className="row wrap">
              <Badge tone="violet">AI 补齐</Badge>
              <Badge tone={task.status === "succeeded" ? "green" : task.status === "failed" ? "pink" : "violet"}>
                {autofillGenerationStatusLabel(task.status)}
              </Badge>
              <strong>{task.name}</strong>
            </div>
            <div className="field-hint task-chapter-label">{taskChapterLabel(task)}</div>
            <div className="field-hint">
              {imageAssetKindLabel(task.assetKind)} · 请求 {task.requestedFields.length} 项
              {task.status === "succeeded" ? ` · 已返回 ${completedFieldCount} 项` : ""}
              {` · ${task.model || "未记录模型"} · ${new Date(task.updatedAt).toLocaleString()}`}
            </div>
            {task.result && completedFieldCount > 0 && (
              <div className="field-hint job-prompt" title={Object.keys(task.result).join("、")}>
                已补齐字段：{Object.keys(task.result).join("、")}
              </div>
            )}
            {task.customRequirement && (
              <div className="field-hint job-prompt" title={task.customRequirement}>
                自定义要求：{task.customRequirement}
              </div>
            )}
          </div>
          <div className="row wrap job-card-actions">
            {task.status === "queued" && <Button small variant="danger" icon={<X size={13} />}
              title="取消此排队资料任务，保留一条已取消记录"
              onClick={() => cancelQueuedTask(task.id)}>取消排队</Button>}
            {(task.status === "failed" || task.bindingWarning) && (
              <Button small variant="ghost" onClick={() => setView("image")}>
                返回图像工作台
              </Button>
            )}
            <Button
              small
              variant={task.status === "running" ? "ghost" : "danger"}
              icon={<Trash2 size={13} />}
              disabled={task.status === "running"}
              title={task.status === "running" ? "资料补齐已开始，完成或失败后可删除" : task.status === "queued" ? "直接移出队列并删除，不再提交资料补齐" : "删除任务记录，已保存资料保留"}
              onClick={() => removeTask(task.id)}
            >
              {task.status === "running" ? "不可删除" : "删除"}
            </Button>
          </div>
        </div>
        {task.bindingWarning && <div className="hint-box compact-hint">{task.bindingWarning}</div>}
        {task.error && <div className="prompt-validation invalid">{formatUserFacingError(task.error)}</div>}
      </Card>
    );
  };
  return (
    <div className="grid jobs-view">
      <SectionHeading eyebrow="GENERATION JOBS" title="生成任务" description="图片、视频和资料任务分开查看，状态与操作互不混杂。" />
      <Card className="soft generation-task-browser">
        <div className="row-between" style={{ marginBottom: 10 }}>
          <label className="row">
            <span>章节范围</span>
            <select value={chapterFilter} onChange={(event) => setChapterFilter(event.target.value)} aria-label="任务章节筛选">
              <option value="all">全项目 · 全部章节</option>
              {state.project.sourceDocuments.map((chapter) => <option key={chapter.id} value={chapter.id}>
                {chapter.name}{chapter.archived ? "（已归档）" : ""}
              </option>)}
              <option value="shared">项目共享 / 历史任务</option>
            </select>
          </label>
          <span className="field-hint">{chapterFilter === "all" ? "显示全项目任务" : `当前范围 ${chapterFilteredTasks.length} 项`} · 后台任务持续运行</span>
        </div>
        <div className="generation-task-tabs" role="tablist" aria-label="任务分类">
          {(["image", "video", "autofill"] as const).map((category) => {
            const meta = taskCategoryMeta[category];
            const active = activeTaskCategory === category;
            const Icon = category === "image" ? ImageIcon : category === "video" ? Film : FileText;
            return (
              <button
                key={category}
                type="button"
                id={`generation-task-tab-${category}`}
                className={`generation-task-tab ${active ? "active" : ""}`}
                data-task-category={category}
                role="tab"
                aria-selected={active}
                aria-controls={`generation-task-panel-${category}`}
                aria-label={`${meta.label}，${meta.count} 个`}
                onClick={() => setActiveTaskCategory(category)}
              >
                <Icon size={16} />
                <span>{meta.label}</span>
                <span className="generation-task-count" aria-hidden="true">{meta.count}</span>
              </button>
            );
          })}
        </div>
        <div className="row-between generation-task-category-summary">
          <div>
            <strong>{activeTaskMeta.title}</strong>
            <div className="field-hint">{activeTaskMeta.description}</div>
          </div>
          <Button
            variant="primary"
            icon={activeTaskCategory === "video" ? <Film size={15} /> : activeTaskCategory === "image" ? <ImageIcon size={15} /> : <FileText size={15} />}
            onClick={openActiveTaskSource}
          >
            {activeTaskMeta.actionLabel}
          </Button>
        </div>
      </Card>
      <div
        id={`generation-task-panel-${activeTaskCategory}`}
        className="job-list"
        role="tabpanel"
        aria-labelledby={`generation-task-tab-${activeTaskCategory}`}
        data-active-task-category={activeTaskCategory}
      >
        {activeTaskCategory === "video" && <VideoExecutionControls settings={state.settings}
          onChange={(patch) => setState((current: AppState) => ({ ...current, settings: { ...current.settings, ...patch } }))} />}
        {activeTaskCategory === "image" && imageTasks.map(renderImageTaskCard)}
        {activeTaskCategory === "autofill" && autofillTasks.map(renderAutofillTaskCard)}
        {activeTaskCategory === "video" && videoTaskGroups.map(renderVideoTaskGroup)}
        {!activeTaskMeta.count && (
          <Card>
            <Empty
              title={chapterFilter === "all" ? activeTaskMeta.emptyTitle : "当前章节范围暂无此类任务"}
              description={chapterFilter === "all" ? activeTaskMeta.emptyDescription : "选择“全项目 · 全部章节”可查看其他章节和项目共享的任务。"}
              action={<Button onClick={openActiveTaskSource}>{activeTaskMeta.actionLabel}</Button>}
            />
          </Card>
        )}
      </div>
    </div>
  );
}

function SettingsView(ctx: AppContext) {
  const { state, setState, notify } = ctx;
  type ApiTarget = "text" | "vision" | "image";
  type SettingsPanel = "image" | "text" | "vision" | "video" | "credentials";
  const [testing, setTesting] = useState(false);
  const [settingsPanel, setSettingsPanel] = useState<SettingsPanel>(ctx.openVideoSettings ? "video" : "image");
  const [storagePaths, setStoragePaths] = useState<{
    dataRoot: string;
    sessionData: string;
    cache: string;
    temp: string;
    logs: string;
  } | null>(null);
  const [loadingModels, setLoadingModels] = useState<
    "text" | "vision" | "image" | null
  >(null);
  const [modelOptions, setModelOptions] = useState<
    Record<"text" | "vision" | "image", string[]>
  >({ text: [], vision: [], image: [] });
  const [modelPickerTarget, setModelPickerTarget] = useState<ApiTarget | null>(null);
  const modelSourceKeysRef = useRef<Partial<Record<ApiTarget, string>>>({});
  const modelFetchInFlightRef = useRef(false);
  const settingsPanelRef = useRef(settingsPanel);
  settingsPanelRef.current = settingsPanel;
  const [selectedCredentialId, setSelectedCredentialId] = useState(
    () => state.settings.apiCredentialBook[0]?.id || "",
  );
  const [credentialDraft, setCredentialDraft] = useState(() =>
    credentialDraftFromEntry(state.settings.apiCredentialBook[0]),
  );
  const [credentialSelections, setCredentialSelections] = useState<
    Record<ApiTarget, string>
  >(() => ({
    text: state.settings.apiCredentialBook[0]?.id || "",
    vision: state.settings.apiCredentialBook[0]?.id || "",
    image: state.settings.apiCredentialBook[0]?.id || "",
  }));
  const settings: AppState["settings"] = state.settings;
  const modelConnectionKey = (target: ApiTarget, source: AppState["settings"] = settings): string => {
    const api = target === "text" ? source.textApi : target === "vision" ? source.visionApi : source.imageApi;
    return JSON.stringify([
      target === "text" ? source.activeTextApiProfileId : target === "vision" ? source.activeVisionApiProfileId : source.activeImageApiProfileId,
      target === "image" ? source.imageApi.backend : target === "text" ? source.textApi.provider : source.visionApi.provider,
      api.baseUrl.trim(), api.apiKey,
    ]);
  };
  const modelsFor = (target: ApiTarget): string[] => modelSourceKeysRef.current[target] === modelConnectionKey(target)
    ? modelOptions[target] : [];
  const openModelPicker = (target: ApiTarget) => {
    if (modelSourceKeysRef.current[target] !== modelConnectionKey(target, ctx.getCurrentState().settings)) return;
    if (modelsFor(target).length) setModelPickerTarget(target);
  };
  useEffect(() => {
    const desktop = window.lianhuaDesktop;
    desktop
      ?.storagePaths?.()
      .then((paths) => setStoragePaths(paths))
      .catch(() => undefined);
  }, []);
  const patchSettings = (patch: Partial<AppState["settings"]>) =>
    setState((current: AppState) => ({
      ...current,
      settings: { ...current.settings, ...patch },
    }));
  const patchText = (patch: Partial<AppState["settings"]["textApi"]>) =>
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        textApi: { ...current.settings.textApi, ...patch },
        textApiProfiles: current.settings.textApiProfiles.map((item) =>
          item.id === current.settings.activeTextApiProfileId
            ? { ...item, ...patch, updatedAt: Date.now() }
            : item,
        ),
      },
    }));
  const patchVision = (patch: Partial<AppState["settings"]["visionApi"]>) =>
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        visionApi: { ...current.settings.visionApi, ...patch },
        visionApiProfiles: current.settings.visionApiProfiles.map((item) =>
          item.id === current.settings.activeVisionApiProfileId
            ? { ...item, ...patch, updatedAt: Date.now() }
            : item,
        ),
      },
    }));
  const patchImage = (patch: Partial<AppState["settings"]["imageApi"]>) =>
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        imageApi: { ...current.settings.imageApi, ...patch },
        imageApiProfiles: current.settings.imageApiProfiles.map((item) =>
          item.id === current.settings.activeImageApiProfileId
            ? { ...item, ...patch, updatedAt: Date.now() }
            : item,
        ),
      },
    }));
  const updatePrivateNetworkAccess = async (allowed: boolean) => {
    const bridge = desktopBridge();
    if (!bridge?.updateRecoveryConfig) {
      notify("本机与局域网访问开关仅在桌面应用中生效。", "error");
      return;
    }
    try {
      const recovery = await bridge.updateRecoveryConfig({ allowPrivateNetwork: allowed });
      ctx.setRecoveryStatus((current: RecoveryStatus | null) => (
        current ? { ...current, recovery } : current
      ));
      notify(allowed ? "已允许访问本机与局域网模型端点。" : "已关闭本机与局域网模型端点访问。");
    } catch (error) {
      notify(error instanceof Error ? error.message : "本机网络访问设置保存失败。", "error");
    }
  };

  const profileMeta = {
    text: {
      profiles: "textApiProfiles",
      active: "activeTextApiProfileId",
      config: "textApi",
      label: "文本",
    },
    vision: {
      profiles: "visionApiProfiles",
      active: "activeVisionApiProfileId",
      config: "visionApi",
      label: "视觉",
    },
    image: {
      profiles: "imageApiProfiles",
      active: "activeImageApiProfileId",
      config: "imageApi",
      label: "图像",
    },
  } as const;
  const stripProfileMeta = (profile: any) => {
    const {
      id: _id,
      name: _name,
      createdAt: _createdAt,
      updatedAt: _updatedAt,
      ...config
    } = profile;
    return config;
  };
  const selectProfile = (target: ApiTarget, id: string) => {
    const meta = profileMeta[target];
    const profile = (settings[meta.profiles] as any[]).find(
      (item) => item.id === id,
    );
    if (!profile) return;
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        [meta.active]: id,
        [meta.config]: stripProfileMeta(profile),
      } as AppState["settings"],
    }));
    notify(`已切换到${meta.label}配置：${profile.name}`);
  };
  const createProfile = (target: ApiTarget) => {
    const meta = profileMeta[target];
    const t = Date.now();
    const currentConfig = settings[meta.config] as any;
    const profile = {
      ...currentConfig,
      id: createId(`${target}_api`),
      name: `新建${meta.label}配置`,
      baseUrl: "",
      apiKey: "",
      model: "",
      ...(target === "image"
        ? {
            workflowJson: "",
            comfyuiWorkflows: [],
            activeComfyuiWorkflowId: "",
            comfyuiPathMode: "preset",
            comfyuiPromptPath: "/prompt",
          }
        : {}),
      createdAt: t,
      updatedAt: t,
    };
    const profiles = [...(settings[meta.profiles] as any[]), profile];
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        [meta.profiles]: profiles,
        [meta.active]: profile.id,
        [meta.config]: stripProfileMeta(profile),
      } as AppState["settings"],
    }));
    notify(`已创建${meta.label} API 配置。`);
  };
  const renameProfile = (target: ApiTarget, name: string) => {
    const meta = profileMeta[target];
    const activeId = settings[meta.active] as string | null;
    const profiles = (settings[meta.profiles] as any[]).map((item) =>
      item.id === activeId ? { ...item, name, updatedAt: Date.now() } : item,
    );
    patchSettings({ [meta.profiles]: profiles } as Partial<
      AppState["settings"]
    >);
  };
  const saveProfile = (target: ApiTarget) => {
    const meta = profileMeta[target];
    const activeId = settings[meta.active] as string | null;
    const config = settings[meta.config] as any;
    const profiles = (settings[meta.profiles] as any[]).map((item) =>
      item.id === activeId
        ? { ...item, ...config, updatedAt: Date.now() }
        : item,
    );
    patchSettings({ [meta.profiles]: profiles } as Partial<
      AppState["settings"]
    >);
    notify(`${meta.label} API 当前配置已保存。`);
  };
  const deleteProfile = (target: ApiTarget) => {
    const meta = profileMeta[target];
    const activeId = settings[meta.active] as string | null;
    let profiles = (settings[meta.profiles] as any[]).filter(
      (item) => item.id !== activeId,
    );
    if (!profiles.length) {
      const t = Date.now();
      profiles = [
        {
          ...(settings[meta.config] as any),
          id: createId(`${target}_api`),
          name: `默认${meta.label}配置`,
          baseUrl: "",
          apiKey: "",
          model: "",
          ...(target === "image"
            ? {
                workflowJson: "",
                comfyuiWorkflows: [],
                activeComfyuiWorkflowId: "",
                comfyuiPathMode: "preset",
                comfyuiPromptPath: "/prompt",
              }
            : {}),
          createdAt: t,
          updatedAt: t,
        },
      ];
    }
    const next = profiles[0];
    setState((current: AppState) => ({
      ...current,
      settings: {
        ...current.settings,
        [meta.profiles]: profiles,
        [meta.active]: next.id,
        [meta.config]: stripProfileMeta(next),
      } as AppState["settings"],
    }));
    notify(`已删除${meta.label} API 配置。`);
  };

  const selectCredentialForEdit = (id: string) => {
    setSelectedCredentialId(id);
    const entry = settings.apiCredentialBook.find((item) => item.id === id);
    setCredentialDraft(credentialDraftFromEntry(entry));
  };
  const saveCredential = () => {
    const baseUrl = credentialDraft.baseUrl.trim();
    const apiKey = credentialDraft.apiKey.trim();
    if (!baseUrl || !apiKey) {
      notify("密码本需要填写 API 地址和 API 密钥。", "error");
      return;
    }
    const t = Date.now();
    const existing = settings.apiCredentialBook.find(
      (item) => item.id === selectedCredentialId,
    );
    const entry: ApiCredentialEntry = existing
      ? {
          ...existing,
          name: credentialDraft.name.trim() || "未命名 API",
          baseUrl,
          apiKey,
          updatedAt: t,
        }
      : {
          id: createId("api_credential"),
          name:
            credentialDraft.name.trim() ||
            baseUrl.replace(/^https?:\/\//i, "").replace(/\/v1\/?$/i, ""),
          baseUrl,
          apiKey,
          createdAt: t,
          updatedAt: t,
        };
    const entries = existing
      ? settings.apiCredentialBook.map((item) =>
          item.id === existing.id ? entry : item,
        )
      : [...settings.apiCredentialBook, entry];
    patchSettings({ apiCredentialBook: entries });
    setSelectedCredentialId(entry.id);
    setCredentialSelections((current) => ({
      text: current.text || entry.id,
      vision: current.vision || entry.id,
      image: current.image || entry.id,
    }));
    notify(existing ? "密码本条目已更新。" : "已保存到 API 地址及密码本。");
  };
  const deleteCredential = () => {
    if (!selectedCredentialId) return;
    const entries = settings.apiCredentialBook.filter(
      (item) => item.id !== selectedCredentialId,
    );
    patchSettings({ apiCredentialBook: entries });
    const nextId = entries[0]?.id || "";
    setSelectedCredentialId(nextId);
    setCredentialDraft(credentialDraftFromEntry(entries[0]));
    setCredentialSelections((current) => ({
      text: current.text === selectedCredentialId ? nextId : current.text,
      vision: current.vision === selectedCredentialId ? nextId : current.vision,
      image: current.image === selectedCredentialId ? nextId : current.image,
    }));
    notify("密码本条目已删除。");
  };
  const applyCredential = (target: ApiTarget) => {
    const id =
      credentialSelections[target] || settings.apiCredentialBook[0]?.id;
    const entry = settings.apiCredentialBook.find((item) => item.id === id);
    if (!entry) {
      notify("密码本暂无可用条目，请先添加。", "error");
      return;
    }
    if (target === "text")
      patchText({ baseUrl: entry.baseUrl, apiKey: entry.apiKey });
    if (target === "vision")
      patchVision({ baseUrl: entry.baseUrl, apiKey: entry.apiKey });
    if (target === "image")
      patchImage({ baseUrl: entry.baseUrl, apiKey: entry.apiKey });
    notify(`已从密码本填充：${entry.name}`);
  };
  const renderProfileTools = (target: ApiTarget) => {
    const meta = profileMeta[target];
    const profiles = settings[meta.profiles] as any[];
    const activeId = settings[meta.active] as string | null;
    const activeProfile =
      profiles.find((item) => item.id === activeId) || profiles[0];
    return (
      <div className="api-profile-box">
        <div className="api-profile-select">
          <select
            value={activeProfile?.id || ""}
            onChange={(event) => selectProfile(target, event.target.value)}
          >
            {profiles.map((item) => (
              <option key={item.id} value={item.id}>
                {item.id === activeId ? "● 当前 · " : ""}
                {item.name}
              </option>
            ))}
          </select>
          <input
            value={activeProfile?.name || ""}
            onChange={(event) => renameProfile(target, event.target.value)}
            placeholder="配置名称"
          />
        </div>
        <div className="api-profile-actions">
          <Button
            small
            icon={<Plus size={13} />}
            onClick={() => createProfile(target)}
          >
            新建
          </Button>
          <Button
            small
            icon={<Save size={13} />}
            onClick={() => saveProfile(target)}
          >
            保存
          </Button>
          <Button
            small
            variant="danger"
            icon={<Trash2 size={13} />}
            onClick={() => deleteProfile(target)}
          >
            删除
          </Button>
        </div>
      </div>
    );
  };
  const renderCredentialFill = (target: ApiTarget) => (
    <div className="credential-fill-row">
      <select
        value={
          credentialSelections[target] ||
          settings.apiCredentialBook[0]?.id ||
          ""
        }
        onChange={(event) =>
          setCredentialSelections((current) => ({
            ...current,
            [target]: event.target.value,
          }))
        }
        disabled={!settings.apiCredentialBook.length}
      >
        {settings.apiCredentialBook.length ? (
          settings.apiCredentialBook.map((entry) => (
            <option key={entry.id} value={entry.id}>
              {entry.name} · {entry.baseUrl}
            </option>
          ))
        ) : (
          <option value="">密码本暂无条目</option>
        )}
      </select>
      <Button
        small
        icon={<BookOpen size={13} />}
        onClick={() => applyCredential(target)}
        disabled={!settings.apiCredentialBook.length}
      >
        快速填充
      </Button>
    </div>
  );
  const testConnection = async () => {
    setTesting(true);
    try {
      const result = await testTextConnection(settings.textApi);
      notify(`文本模型连接成功：${result.slice(0, 80)}`);
    } catch (error) {
      notify(error instanceof Error ? error.message : "连接失败", "error");
    } finally {
      setTesting(false);
    }
  };
  const handleFetchModels = async (target: "text" | "vision" | "image") => {
    if (modelFetchInFlightRef.current) return;
    const currentSettings = ctx.getCurrentState().settings;
    if (target === "image" && currentSettings.imageApi.backend !== "openai") {
      notify(
        "当前图像后端不提供 OpenAI 模型列表，请直接填写模型或工作流名称。",
      );
      return;
    }
    const config =
      target === "text"
        ? currentSettings.textApi
        : target === "vision"
          ? currentSettings.visionApi
          : {
              provider: "openai_compatible" as const,
              baseUrl: currentSettings.imageApi.baseUrl,
              apiKey: currentSettings.imageApi.apiKey,
            };
    const sourceKey = modelConnectionKey(target, currentSettings);
    modelFetchInFlightRef.current = true;
    setLoadingModels(target);
    try {
      const models = await fetchAvailableModels(config);
      if (sourceKey !== modelConnectionKey(target, ctx.getCurrentState().settings)) {
        notify("API 配置已改变，本次旧模型列表已忽略，请重新获取。");
        return;
      }
      modelSourceKeysRef.current[target] = sourceKey;
      setModelOptions((current) => ({ ...current, [target]: models }));
      if (settingsPanelRef.current === target) setModelPickerTarget(target);
      notify(
        `已获取 ${models.length} 个${target === "text" ? "文本" : target === "vision" ? "视觉" : "图像"}模型，可在完整列表中搜索选择，也可继续手动输入。`,
      );
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "获取模型列表失败",
        "error",
      );
    } finally {
      modelFetchInFlightRef.current = false;
      setLoadingModels(null);
    }
  };
  const clearKeys = () => {
    patchSettings({
      textApi: { ...settings.textApi, apiKey: "" },
      visionApi: { ...settings.visionApi, apiKey: "" },
      imageApi: { ...settings.imageApi, apiKey: "" },
      videoTaskApi: { ...settings.videoTaskApi, apiKey: "" },
      comfyuiVideo: settings.comfyuiVideo ? { ...settings.comfyuiVideo, apiKey: "" } : undefined,
      runningHubVideo: settings.runningHubVideo ? { ...settings.runningHubVideo, apiKey: "" } : undefined,
      videoApiProfiles: settings.videoApiProfiles?.map((profile) => ({ ...profile, apiKey: "" })),
      apiCredentialBook: settings.apiCredentialBook.map((item) => ({
        ...item,
        apiKey: "",
      })),
      textApiProfiles: settings.textApiProfiles.map((item) => ({
        ...item,
        apiKey: "",
      })),
      visionApiProfiles: settings.visionApiProfiles.map((item) => ({
        ...item,
        apiKey: "",
      })),
      imageApiProfiles: settings.imageApiProfiles.map((item) => ({
        ...item,
        apiKey: "",
      })),
    });
    setCredentialDraft((current) => ({ ...current, apiKey: "" }));
    notify("已清空当前接口、全部保存配置和密码本中的 API 密钥。");
  };
  return (
    <div className="settings-page settings-view">
      {modelPickerTarget && (
        <ModelPickerModal
          models={modelsFor(modelPickerTarget)}
          currentModel={modelPickerTarget === "text" ? settings.textApi.model : modelPickerTarget === "vision" ? settings.visionApi.model : settings.imageApi.model}
          title={`选择${modelPickerTarget === "text" ? "文本" : modelPickerTarget === "vision" ? "视觉" : "图像"}模型`}
          fontScalePercent={settings.uiFontScalePercent}
          onClose={() => setModelPickerTarget(null)}
          onSelect={(model) => {
            const target = modelPickerTarget;
            if (modelSourceKeysRef.current[target] !== modelConnectionKey(target, ctx.getCurrentState().settings)) {
              notify("API 配置已改变，请重新获取模型列表。", "error");
              setModelPickerTarget(null);
              return;
            }
            if (target === "text") patchText({ model });
            else if (target === "vision") patchVision({ model });
            else patchImage({ model });
            setModelPickerTarget(null);
          }}
        />
      )}
      <SectionHeading
        eyebrow="API SETTINGS"
        title="API 设置"
        description="配置文本、图像与视频生成连接；提示词在提示词导演台制作，成片在视频导演台生成。"
        action={
          <div className="row">
            <Button
              small
              variant="danger"
              icon={<Trash2 size={14} />}
              onClick={clearKeys}
            >
              清空密钥
            </Button>
            <Button
              small
              icon={<Save size={15} />}
              onClick={() => notify("设置已自动保存到本地。")}
            >
              保存设置
            </Button>
          </div>
        }
      />
      <div className="settings-boundary">
        <AlertTriangle size={15} />
        <span>
          默认不向外部接口提交；只有显式启用并配置对应的图像或视频 API 后，才会发出生成请求。
        </span>
      </div>

      <div className="page-switcher settings-api-tabs" role="tablist" aria-label="API 设置分类">
        <button
          type="button"
          role="tab"
          aria-selected={settingsPanel === "image"}
          aria-controls="settings-panel-stage"
          data-settings-panel="image"
          className={`segment ${settingsPanel === "image" ? "active violet" : ""}`}
          onClick={() => setSettingsPanel("image")}
        >
          <ImageIcon size={14} />
          图片 API
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={settingsPanel === "text"}
          aria-controls="settings-panel-stage"
          data-settings-panel="text"
          className={`segment ${settingsPanel === "text" ? "active" : ""}`}
          onClick={() => setSettingsPanel("text")}
        >
          <Brain size={14} />
          文本 API
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={settingsPanel === "vision"}
          aria-controls="settings-panel-stage"
          data-settings-panel="vision"
          className={`segment ${settingsPanel === "vision" ? "active cyan" : ""}`}
          onClick={() => setSettingsPanel("vision")}
        >
          <Eye size={14} />
          视觉 API
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={settingsPanel === "video"}
          aria-controls="settings-panel-stage"
          data-settings-panel="video"
          className={`segment ${settingsPanel === "video" ? "active cyan" : ""}`}
          onClick={() => setSettingsPanel("video")}
        >
          <Play size={14} />
          视频生成
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={settingsPanel === "credentials"}
          aria-controls="settings-panel-stage"
          data-settings-panel="credentials"
          className={`segment ${settingsPanel === "credentials" ? "active amber" : ""}`}
          onClick={() => setSettingsPanel("credentials")}
        >
          <BookOpen size={14} />
          密码本
        </button>
      </div>

      <div
        id="settings-panel-stage"
        className="settings-panel-stage"
        data-active-panel={settingsPanel}
        role="tabpanel"
      >
      {settingsPanel === "video" && (
        <VideoGenerationSettings settings={settings} onChange={patchSettings}
          getCurrentSettings={() => ctx.getCurrentState().settings}
          allowPrivateNetwork={Boolean(ctx.recoveryStatus?.recovery.allowPrivateNetwork)}
          onPrivateNetworkChange={(allowed) => { void updatePrivateNetworkAccess(allowed); }} />
      )}

      {settingsPanel === "credentials" && (
      <Card className="credential-book-card credential-panel-card api-tone-amber">
        <div className="card-title">
          <div>
            <h2>API 地址及密码本</h2>
            <p>
              统一保存多组 Base URL 与 API
              Key，文本、视觉、图像接口都能一键填充。
            </p>
          </div>
          <BookOpen size={18} color="var(--amber)" />
        </div>
        <div className="credential-manager-grid">
          <Field label="已保存条目">
            <select
              value={selectedCredentialId}
              onChange={(event) => selectCredentialForEdit(event.target.value)}
            >
              <option value="">新建条目</option>
              {settings.apiCredentialBook.map((entry) => (
                <option key={entry.id} value={entry.id}>
                  {entry.name} · {entry.baseUrl}
                </option>
              ))}
            </select>
          </Field>
          <Field label="名称">
            <input
              value={credentialDraft.name}
              onChange={(event) =>
                setCredentialDraft((current) => ({
                  ...current,
                  name: event.target.value,
                }))
              }
              placeholder="主用 / 备用 / 平台名称"
            />
          </Field>
          <Field label="API 地址 / Base URL">
            <input
              value={credentialDraft.baseUrl}
              onChange={(event) =>
                setCredentialDraft((current) => ({
                  ...current,
                  baseUrl: event.target.value,
                }))
              }
              placeholder="https://api.example.com/v1"
            />
          </Field>
          <Field label="API 密钥">
            <input
              type="password"
              value={credentialDraft.apiKey}
              onChange={(event) =>
                setCredentialDraft((current) => ({
                  ...current,
                  apiKey: event.target.value,
                }))
              }
              placeholder="sk-..."
            />
          </Field>
          <div className="credential-manager-actions">
            <Button
              small
              icon={<Plus size={13} />}
              onClick={() => {
                setSelectedCredentialId("");
                setCredentialDraft(credentialDraftFromEntry(undefined));
              }}
            >
              新建
            </Button>
            <Button
              small
              variant="primary"
              icon={<Save size={13} />}
              onClick={saveCredential}
            >
              {selectedCredentialId ? "更新" : "保存"}
            </Button>
            <Button
              small
              variant="danger"
              icon={<Trash2 size={13} />}
              onClick={deleteCredential}
              disabled={!selectedCredentialId}
            >
              删除
            </Button>
          </div>
        </div>
      </Card>
      )}

      {(settingsPanel === "text" || settingsPanel === "vision" || settingsPanel === "image") && (
      <div className="api-grid single-api-grid">
        {settingsPanel === "text" && (
          <Card className="api-card text-api-card api-tone-pink">
            <div className="card-title">
              <div>
                <h2>文本 / 转换器 API</h2>
                <p>剧情解析、镜头数量建议与最终视频提示词自动转化。</p>
              </div>
              <Brain size={19} color="var(--pink)" />
            </div>
            {renderProfileTools("text")}
            {renderCredentialFill("text")}
            <label className="check-row">
              <input
                type="checkbox"
                checked={settings.textApi.enabled}
                onChange={(event) =>
                  patchText({ enabled: event.target.checked })
                }
              />
              启用文本模型接口
            </label>
            <div className="api-fields-two">
              <Field label="服务商">
                <select
                  value={settings.textApi.provider}
                  onChange={(event) =>
                    patchText({
                      provider: event.target
                        .value as AppState["settings"]["textApi"]["provider"],
                    })
                  }
                >
                  <option value="openai_compatible">OpenAI 兼容</option>
                  <option value="deepseek">DeepSeek</option>
                  <option value="gemini">Gemini 兼容</option>
                  <option value="claude">Claude</option>
                </select>
              </Field>
              <Field label="模型名称">
                <div className="model-control">
                  <input
                    value={settings.textApi.model}
                    onChange={(event) =>
                      patchText({ model: event.target.value })
                    }
                    placeholder="可手动输入或获取列表"
                  />
                  <Button small className="model-picker-trigger" icon={<ChevronDown size={13} />}
                    title={`选择文本模型（${modelsFor("text").length} 个）`}
                    disabled={!modelsFor("text").length || loadingModels !== null} onClick={() => openModelPicker("text")} />
                  <Button
                    small
                    icon={<RefreshCw size={13} />}
                    disabled={loadingModels !== null}
                    onClick={() => handleFetchModels("text")}
                  >
                    {loadingModels === "text" ? "获取中" : "获取模型"}
                  </Button>
                </div>
              </Field>
            </div>
            <Field
              label="API 地址"
              hint="可填写基础地址或完整 /v1/chat/completions。"
            >
              <input
                value={settings.textApi.baseUrl}
                onChange={(event) => patchText({ baseUrl: event.target.value })}
                placeholder="https://api.example.com/v1"
              />
            </Field>
            <Field label="API 密钥">
              <input
                type="password"
                value={settings.textApi.apiKey}
                onChange={(event) => patchText({ apiKey: event.target.value })}
                placeholder="桌面版使用 Windows 系统加密保存"
              />
            </Field>
            <div className="api-fields-two">
              <Field label="温度">
                <input
                  type="number"
                  min={0}
                  max={2}
                  step={0.05}
                  value={settings.textApi.temperature}
                  onChange={(event) =>
                    patchText({ temperature: Number(event.target.value) })
                  }
                />
              </Field>
              <Field label="最大输出 Token">
                <input
                  type="number"
                  min={500}
                  max={100000}
                  step={500}
                  value={settings.textApi.maxTokens}
                  onChange={(event) =>
                    patchText({ maxTokens: Number(event.target.value) })
                  }
                />
              </Field>
            </div>
            <div className="api-card-actions">
              <Button
                small
                icon={<Zap size={15} />}
                disabled={testing}
                onClick={testConnection}
              >
                {testing ? "测试中…" : "测试连接"}
              </Button>
            </div>
          </Card>
        )}

        {settingsPanel === "vision" && (
          <Card className="api-card vision-api-card api-tone-cyan">
            <div className="card-title">
              <div>
                <h2>视觉分析 API</h2>
                <p>读取角色参考图、场景图与实际九宫格。</p>
              </div>
              <Eye size={19} color="var(--cyan)" />
            </div>
            {renderProfileTools("vision")}
            {renderCredentialFill("vision")}
            <label className="check-row">
              <input
                type="checkbox"
                checked={settings.visionApi.enabled}
                onChange={(event) =>
                  patchVision({ enabled: event.target.checked })
                }
              />
              启用视觉分析接口
            </label>
            <div className="api-fields-two">
              <Field label="服务商">
                <select
                  value={settings.visionApi.provider}
                  onChange={(event) =>
                    patchVision({
                      provider: event.target
                        .value as AppState["settings"]["visionApi"]["provider"],
                    })
                  }
                >
                  <option value="openai_compatible">OpenAI 兼容</option>
                  <option value="gemini">Gemini 兼容</option>
                  <option value="claude">Claude</option>
                  <option value="deepseek">DeepSeek 兼容</option>
                </select>
              </Field>
              <Field label="视觉模型">
                <div className="model-control">
                  <input
                    value={settings.visionApi.model}
                    onChange={(event) =>
                      patchVision({ model: event.target.value })
                    }
                    placeholder="可手动输入或获取列表"
                  />
                  <Button small className="model-picker-trigger" icon={<ChevronDown size={13} />}
                    title={`选择视觉模型（${modelsFor("vision").length} 个）`}
                    disabled={!modelsFor("vision").length || loadingModels !== null} onClick={() => openModelPicker("vision")} />
                  <Button
                    small
                    icon={<RefreshCw size={13} />}
                    disabled={loadingModels !== null}
                    onClick={() => handleFetchModels("vision")}
                  >
                    {loadingModels === "vision" ? "获取中" : "获取模型"}
                  </Button>
                </div>
              </Field>
            </div>
            <Field label="API 地址">
              <input
                value={settings.visionApi.baseUrl}
                onChange={(event) =>
                  patchVision({ baseUrl: event.target.value })
                }
                placeholder="OpenAI 兼容 Chat Completions 地址"
              />
            </Field>
            <Field label="API 密钥">
              <input
                type="password"
                value={settings.visionApi.apiKey}
                onChange={(event) =>
                  patchVision({ apiKey: event.target.value })
                }
              />
            </Field>
            <div className="hint-box">
              未配置视觉 API
              时，仍可上传参考图并手动填写视觉锚点，只是不自动读取图片内容。
            </div>
          </Card>
        )}

        {settingsPanel === "image" && (
          <Card className="api-card image-api-card api-tone-violet">
            <div className="card-title">
              <div>
                <h2>图像生成 API</h2>
                <p>生成人物、场景、物品与九宫格视觉母版。</p>
              </div>
              <ImageIcon size={19} color="var(--violet)" />
            </div>
            {renderProfileTools("image")}
            {settings.imageApi.backend !== "comfyui" && renderCredentialFill("image")}
            <label className="check-row">
              <input
                type="checkbox"
                checked={settings.imageApi.enabled}
                onChange={(event) =>
                  patchImage({ enabled: event.target.checked })
                }
              />
              启用图像生成接口
            </label>
            <div className={`api-fields-two ${settings.imageApi.backend === "comfyui" ? "comfyui-backend-row" : ""}`}>
              <Field label="后端">
                <select
                  value={settings.imageApi.backend}
                  onChange={(event) =>
                    patchImage({
                      backend: event.target
                        .value as AppState["settings"]["imageApi"]["backend"],
                    })
                  }
                >
                  <option value="openai">OpenAI 兼容</option>
                  <option value="sd_webui">Stable Diffusion WebUI</option>
                  <option value="comfyui">ComfyUI</option>
                  <option value="novelai">NovelAI</option>
                </select>
              </Field>
              {settings.imageApi.backend !== "comfyui" && <Field label="模型 / 工作流">
                <div className="model-control">
                  <input
                    value={settings.imageApi.model}
                    onChange={(event) =>
                      patchImage({ model: event.target.value })
                    }
                    placeholder={
                      settings.imageApi.backend === "sd_webui"
                        ? "SD WebUI 可留空"
                        : "可手动输入或获取列表"
                    }
                  />
                  <Button small className="model-picker-trigger" icon={<ChevronDown size={13} />}
                    title={`选择图像模型（${modelsFor("image").length} 个）`}
                    disabled={!modelsFor("image").length || loadingModels !== null || settings.imageApi.backend !== "openai"}
                    onClick={() => openModelPicker("image")} />
                  <Button
                    small
                    icon={<RefreshCw size={13} />}
                    disabled={
                      loadingModels !== null ||
                      settings.imageApi.backend !== "openai"
                    }
                    onClick={() => handleFetchModels("image")}
                  >
                    {loadingModels === "image" ? "获取中" : "获取模型"}
                  </Button>
                </div>
              </Field>}
            </div>
            {settings.imageApi.backend === "comfyui" ? (
              <>
                <div className="api-fields-two comfyui-connection-fields">
                  <Field label="ComfyUI API 根地址">
                    <input
                      value={settings.imageApi.baseUrl}
                      onChange={(event) => patchImage({ baseUrl: event.target.value })}
                      placeholder="http://127.0.0.1:8188"
                    />
                  </Field>
                  <Field label="API 密钥（可选）">
                    <input
                      type="password"
                      value={settings.imageApi.apiKey}
                      onChange={(event) => patchImage({ apiKey: event.target.value })}
                    />
                  </Field>
                </div>
                <ComfyUISettings
                  config={settings.imageApi}
                  allowPrivateNetwork={Boolean(ctx.recoveryStatus?.recovery.allowPrivateNetwork)}
                  onChange={patchImage}
                  onPrivateNetworkChange={(allowed) => void updatePrivateNetworkAccess(allowed)}
                />
              </>
            ) : (
              <>
                <Field label="API 地址">
                  <input
                    value={settings.imageApi.baseUrl}
                    onChange={(event) => patchImage({ baseUrl: event.target.value })}
                    placeholder={
                      settings.imageApi.backend === "novelai"
                        ? "NovelAI 官方根地址或完整 /ai/generate-image 端点"
                        : "例如 https://api.example.com/v1"
                    }
                  />
                </Field>
                <Field label="API 密钥">
                  <input
                    type="password"
                    value={settings.imageApi.apiKey}
                    onChange={(event) => patchImage({ apiKey: event.target.value })}
                  />
                </Field>
                <div className="field-hint">
                  OpenAI 兼容、Stable Diffusion WebUI 与 NovelAI 均已接入真实出图；NovelAI 使用原生 NAI 标签与 V4 角色提示结构。
                </div>
              </>
            )}
          </Card>
        )}
      </div>
      )}
      </div>
      {storagePaths && (
        <div className="settings-storage">
          <FolderOpen size={15} />
          <span>项目与资产：{storagePaths.dataRoot}</span>
          <span>缓存、日志与托管媒体位于当前数据目录</span>
        </div>
      )}
    </div>
  );
}
